html body .main,
html body .main-content,
html body .content,
html body .blog-posts,
html body .post,
html body .post-outer,
html body .post-card,
html body .stream-card,
html body .sidebar,
html body .sidebar-wrapper,
html body .sidebar-inner,
html body .sidebar .widget,
html body .widget,
html body .widget-content,
html body .blog-post,
html body .article,
html body .article-wrapper,
html body .single-post,
html body .item-view-post,
html body .item-view-page {
  border: none;
  box-shadow: none;
  outline: none;
}

html body .stream-card {
  border-bottom: 1px solid var(--border-color);
  background: var(--card-bg, #ffffff);
}

html body .stream-card:last-child {
  border-bottom: none;
}

html body .main,
html body .main-content,
html body .main-wrapper,
html body .sidebar,
html body .sidebar-inner,
html body .sidebar .widget,
html body .article-wrapper,
html body .post-body-container {
  background: transparent;
}

.test-ad-wrapper {
  width: 100%;
  display: flex;
  justify-content: center;
  align-items: center;
  margin: 20px 0;
  clear: both;
}

.test-ad-box {
  width: 100%;
  max-width: 728px;
  height: 90px;
  background: #f8fafc;
  border: 2px dashed #cbd5e1;
  border-radius: 8px;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  box-sizing: border-box;
  font-family: inherit;
  color: #64748b;
  text-align: center;
  padding: 10px;
  transition: color 0.2s ease-in-out, background-color 0.2s ease-in-out, border-color 0.2s ease-in-out;
}

.test-ad-box:hover {
  border-color: #3b82f6;
  background: #eff6ff;
  color: #1e40af;
}

.test-ad-label {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.5px;
  margin-bottom: 4px;
  opacity: 0.8;
}

.test-ad-dimensions {
  font-size: 13px;
  font-weight: 600;
}

@media (max-width: 768px) {
  .test-ad-box {
    max-width: 300px;
    height: 250px;
  }
}

body {
  --hide-sidebar-val: 1px;
  --hide-sidebar-mobile-val: $(hideSidebarMobile);
  --sidebar-w: clamp(0px, calc((2 - var(--hide-sidebar-val, 1px) / 1px) * 350px), 350px);
}

body.is-homepage { --hide-sidebar-val: $(hideSidebarHome); }
body.is-post { --hide-sidebar-val: $(hideSidebarPost); }
body.is-page { --hide-sidebar-val: $(hideSidebarPage); }
body.is-archive,
body.is-search { --hide-sidebar-val: $(hideSidebarHome); }

.main-wrapper {
  max-width: var(--contentMaxWidth);
  margin-inline: auto;
  margin: 10px auto 60px;
  width: 100%;
  display: flex;
  gap: min(var(--main-gap), calc(var(--sidebar-w) * 999));
  align-items: flex-start;
  box-sizing: border-box;
}

.main-content {
  flex: 1 1 0%;
  width: 100%;
  min-width: 0;
  background: transparent;
  border: none;
  box-shadow: none;
  outline: none;
  transition: max-width 0.25s ease, flex 0.25s ease;
}

.sidebar {
  width: var(--sidebar-w);
  max-width: var(--sidebar-w);
  min-width: 0;
  max-height: calc(var(--sidebar-w) * 9999);
  overflow: hidden;
  box-sizing: border-box;
  flex-shrink: 0;
  background: transparent;
  border: none;
  box-shadow: none;
  outline: none;
  transition: width 0.25s ease, max-height 0.25s ease;
}

.sidebar[aria-hidden="true"] {
  display: none !important;
}

.sidebar-inner.sticky-sidebar {
  position: sticky;
  top: var(--sidebar-sticky-offset);
  display: flex;
  flex-direction: column;
  gap: 32px;
}

.posts-stream {
  display: flex;
  flex-direction: column;
  gap: 24px;
}

.stream-card {
  display: flex;
  gap: 22px;
  padding-bottom: 24px;
  border-bottom: 1px solid var(--border-color);
  align-items: flex-start;
  transition: transform 0.2s ease;
}

.stream-card:last-child {
  border-bottom: none;
}

.stream-thumb-wrap {
  position: relative;
  width: 250px;
  height: 160px;
  flex-shrink: 0;
  border-radius: var(--radius-md);
  overflow: hidden;
  background: var(--card-bg);
  box-shadow: none;
}

.stream-thumb {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 0.4s ease;
  aspect-ratio: 16/10;
}

.stream-card:hover .stream-thumb {
  transform: scale(1.06);
}

.stream-thumb-placeholder {
  width: 100%;
  height: 100%;
  background: linear-gradient(135deg, var(--card-bg), var(--border-color));
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--muted-color);
  font-weight: 800;
  font-size: 0.95rem;
}

.stream-details {
  flex-grow: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
}

.stream-badge-row {
  margin-bottom: 8px;
}

.stream-title {
  font-size: 1.25rem;
  font-weight: 800;
  line-height: 1.4;
  margin-bottom: 10px;
}

.stream-title a {
  color: var(--text-color);
}

.stream-title a:hover {
  color: var(--primary-color);
}

.stream-snippet {
  color: var(--muted-color);
  font-size: 0.9rem;
  line-height: 1.6;
  margin-bottom: 14px;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.stream-meta {
  font-size: 0.78rem;
  color: var(--muted-color);
  display: flex;
  align-items: center;
  gap: 14px;
  font-weight: 600;
}


/* --- SIDEBAR SOCIAL WIDGET (MODERN 2-COLUMN CARDS GRID) --- */
.sidebar-social-sec {
  margin-bottom: 28px !important;
  display: block !important;
  width: 100% !important;
}

.sidebar-social-sec .widget {
  margin: 0 !important;
  padding: 0 !important;
  border: none !important;
  background: transparent !important;
  box-shadow: none !important;
}

.sidebar-social-widget-title {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 1.15rem;
  font-weight: 800;
  color: var(--text-color, #111317);
  margin: 0 0 16px 0;
  padding-bottom: 8px;
  border-bottom: 2px solid var(--border-color, #eaedf1);
  position: relative;
}

.sidebar-social-widget-title::after {
  content: '';
  position: absolute;
  bottom: -2px;
  right: 0;
  width: 45px;
  height: 2px;
  background: var(--primary-color, #f83a5e);
}

[dir="ltr"] .sidebar-social-widget-title::after {
  right: auto;
  left: 0;
}

.sidebar-social-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 10px;
}

.sidebar-social-btn {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 12px;
  border-radius: var(--sidebar-social-radius, 10px);
  background: var(--surface-color, #ffffff);
  border: 1px solid var(--border-color, #eaedf1);
  text-decoration: none !important;
  color: var(--text-color, #111317) !important;
  font-family: var(--body-font, 'Cairo', sans-serif);
  transition: transform 0.22s ease, box-shadow 0.22s ease, border-color 0.22s ease, background 0.22s ease;
  position: relative;
  overflow: hidden;
}

.sidebar-social-btn:hover {
  transform: translateY(-2px);
  box-shadow: 0 6px 16px rgba(0, 0, 0, 0.08);
}

.sidebar-social-icon {
  width: 32px;
  height: 32px;
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  background: rgba(0, 0, 0, 0.04);
  color: var(--text-color, #111317);
  transition: background 0.22s ease, color 0.22s ease;
}

.sidebar-social-icon svg {
  width: 16px;
  height: 16px;
  fill: currentColor;
  display: block;
}

.sidebar-social-meta {
  display: flex;
  flex-direction: column;
  min-width: 0;
  line-height: 1.25;
}

.sidebar-social-name {
  font-size: 0.84rem;
  font-weight: 700;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  text-transform: capitalize;
}

.sidebar-social-action {
  font-size: 0.72rem;
  color: var(--muted-text, #64748b);
  font-weight: 500;
  transition: color 0.2s ease;
}

/* Brand specific styling & hover states */
.sidebar-social-btn[data-network*="facebook"]:hover,
.sidebar-social-btn[data-network*="فيسبوك"]:hover {
  border-color: #1877f2;
  background: rgba(24, 119, 242, 0.06);
}
.sidebar-social-btn[data-network*="facebook"]:hover .sidebar-social-icon,
.sidebar-social-btn[data-network*="فيسبوك"]:hover .sidebar-social-icon {
  background: #1877f2;
  color: #ffffff;
}

.sidebar-social-btn[data-network*="x"]:hover,
.sidebar-social-btn[data-network*="twitter"]:hover,
.sidebar-social-btn[data-network*="تويتر"]:hover {
  border-color: #111317;
  background: rgba(0, 0, 0, 0.05);
}
.sidebar-social-btn[data-network*="x"]:hover .sidebar-social-icon,
.sidebar-social-btn[data-network*="twitter"]:hover .sidebar-social-icon,
.sidebar-social-btn[data-network*="تويتر"]:hover .sidebar-social-icon {
  background: #111317;
  color: #ffffff;
}

.sidebar-social-btn[data-network*="instagram"]:hover,
.sidebar-social-btn[data-network*="انستغرام"]:hover,
.sidebar-social-btn[data-network*="انستقرام"]:hover {
  border-color: #e1306c;
  background: rgba(225, 48, 108, 0.06);
}
.sidebar-social-btn[data-network*="instagram"]:hover .sidebar-social-icon,
.sidebar-social-btn[data-network*="انستغرام"]:hover .sidebar-social-icon,
.sidebar-social-btn[data-network*="انستقرام"]:hover .sidebar-social-icon {
  background: linear-gradient(45deg, #f09433, #e6683c, #dc2743, #cc2366, #bc1888);
  color: #ffffff;
}

.sidebar-social-btn[data-network*="youtube"]:hover,
.sidebar-social-btn[data-network*="يوتيوب"]:hover {
  border-color: #ff0000;
  background: rgba(255, 0, 0, 0.06);
}
.sidebar-social-btn[data-network*="youtube"]:hover .sidebar-social-icon,
.sidebar-social-btn[data-network*="يوتيوب"]:hover .sidebar-social-icon {
  background: #ff0000;
  color: #ffffff;
}

.sidebar-social-btn[data-network*="telegram"]:hover,
.sidebar-social-btn[data-network*="تليجرام"]:hover,
.sidebar-social-btn[data-network*="تيليجرام"]:hover {
  border-color: #229ed9;
  background: rgba(34, 158, 217, 0.06);
}
.sidebar-social-btn[data-network*="telegram"]:hover .sidebar-social-icon,
.sidebar-social-btn[data-network*="تليجرام"]:hover .sidebar-social-icon,
.sidebar-social-btn[data-network*="تيليجرام"]:hover .sidebar-social-icon {
  background: #229ed9;
  color: #ffffff;
}

.sidebar-social-btn[data-network*="whatsapp"]:hover,
.sidebar-social-btn[data-network*="واتساب"]:hover,
.sidebar-social-btn[data-network*="واتس"]:hover {
  border-color: #25d366;
  background: rgba(37, 211, 102, 0.06);
}
.sidebar-social-btn[data-network*="whatsapp"]:hover .sidebar-social-icon,
.sidebar-social-btn[data-network*="واتساب"]:hover .sidebar-social-icon,
.sidebar-social-btn[data-network*="واتس"]:hover .sidebar-social-icon {
  background: #25d366;
  color: #ffffff;
}

.sidebar-social-btn[data-network*="tiktok"]:hover,
.sidebar-social-btn[data-network*="تيك"]:hover {
  border-color: #00f2fe;
  background: rgba(0, 242, 254, 0.06);
}
.sidebar-social-btn[data-network*="tiktok"]:hover .sidebar-social-icon,
.sidebar-social-btn[data-network*="تيك"]:hover .sidebar-social-icon {
  background: #010101;
  color: #00f2fe;
}

.sidebar-social-btn[data-network*="linkedin"]:hover,
.sidebar-social-btn[data-network*="لينكد"]:hover {
  border-color: #0a66c2;
  background: rgba(10, 102, 194, 0.06);
}
.sidebar-social-btn[data-network*="linkedin"]:hover .sidebar-social-icon,
.sidebar-social-btn[data-network*="لينكد"]:hover .sidebar-social-icon {
  background: #0a66c2;
  color: #ffffff;
}

.sidebar-social-btn[data-network*="pinterest"]:hover,
.sidebar-social-btn[data-network*="بينترست"]:hover {
  border-color: #e60023;
  background: rgba(230, 0, 35, 0.06);
}
.sidebar-social-btn[data-network*="pinterest"]:hover .sidebar-social-icon,
.sidebar-social-btn[data-network*="بينترست"]:hover .sidebar-social-icon {
  background: #e60023;
  color: #ffffff;
}

/* Dark theme overrides */
[data-theme="dark"] .sidebar-social-btn,
body.dark-mode .sidebar-social-btn {
  background: rgba(255, 255, 255, 0.03);
  border-color: rgba(255, 255, 255, 0.08);
  color: #ffffff !important;
}

[data-theme="dark"] .sidebar-social-icon,
body.dark-mode .sidebar-social-icon {
  background: rgba(255, 255, 255, 0.08);
  color: #ffffff;
}

[data-theme="dark"] .sidebar-social-action,
body.dark-mode .sidebar-social-action {
  color: #94a3b8;
}

[data-theme="dark"] .sidebar-social-btn[data-network*="x"]:hover .sidebar-social-icon,
[data-theme="dark"] .sidebar-social-btn[data-network*="twitter"]:hover .sidebar-social-icon,
[data-theme="dark"] .sidebar-social-btn[data-network*="تويتر"]:hover .sidebar-social-icon {
  background: #ffffff;
  color: #000000;
}

.sidebar .widget {
  background: transparent;
  border: none;
  border-radius: 0;
  padding: 0 0 32px 0;
  box-shadow: none;
  outline: none;
}

.widget-header-row {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 20px;
  padding-bottom: 10px;
  border-bottom: 2px solid var(--border-color);
  position: relative;
}

.widget-header-row::after {
  content: '';
  position: absolute;
  bottom: -2px;
  right: 0;
  width: 45px;
  height: 2px;
  background: var(--primary-color);
}

.widget-title {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 1.05rem;
  font-weight: 900;
  text-transform: uppercase;
  color: var(--text-color);
  margin: 0;
}

.editors-picks-heading {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 1.4rem;
  font-weight: 900;
  color: var(--primary-color);
  margin-bottom: 20px;
  letter-spacing: -0.3px;
}

.editors-picks-list {
  display: flex;
  flex-direction: column;
  gap: 26px;
}

.editors-pick-card {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.editors-pick-thumb-wrap {
  width: 100%;
  aspect-ratio: 16/10;
  border-radius: var(--radius-sm);
  overflow: hidden;
  background: var(--border-color);
  box-shadow: none;
  position: relative;
}

.editors-pick-thumb {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 0.4s ease;
  aspect-ratio: 16/10;
}

.editors-pick-card:hover .editors-pick-thumb {
  transform: scale(1.05);
}

.editors-pick-title {
  font-size: 1.05rem;
  font-weight: 800;
  line-height: 1.45;
  margin: 0;
}

.editors-pick-title a {
  color: var(--text-color);
}

.editors-pick-title a:hover {
  color: var(--primary-color);
}

.tags-cloud-wrap {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.tags-cloud-wrap a {
  background: var(--bg-color);
  border: 1px solid var(--border-color);
  color: var(--text-color);
  padding: 6px 12px;
  border-radius: var(--radius-sm);
  font-size: 0.82rem;
  font-weight: 700;
  transition: color 0.2s ease, background-color 0.2s ease, border-color 0.2s ease;
}

.tags-cloud-wrap a:hover {
  background: var(--primary-color);
  color: #ffffff;
  border-color: var(--primary-color);
}

.author-profile-block {
  text-align: center;
}

.author-profile-img {
  width: 84px;
  height: 84px;
  border-radius: 50%;
  margin: 0 auto 12px;
  border: 3px solid var(--primary-color);
  object-fit: cover;
}

.author-profile-name {
  font-size: 1.15rem;
  font-weight: 800;
  margin-bottom: 6px;
}

.author-profile-bio {
  font-size: 0.88rem;
  color: var(--muted-color);
  line-height: 1.55;
}

.article-wrapper {
  background: transparent;
  border: none;
  border-radius: 0;
  padding: 0 0 36px 0;
  box-shadow: none;
  outline: none;
}

.article-breadcrumbs {
  font-size: 0.82rem;
  color: var(--muted-color);
  margin-bottom: 18px;
  display: flex;
  align-items: center;
  gap: 8px;
  font-weight: 600;
}

.article-breadcrumbs a {
  color: var(--muted-color);
}

.article-breadcrumbs a:hover {
  color: var(--primary-color);
}

.article-headline {
  font-size: 2.3rem;
  line-height: 1.3;
  margin-bottom: 18px;
  color: var(--text-color);
  font-weight: 900;
}

body {
  --show-featured-val: $(showPostFeaturedImage);
}

.article-featured-img {
  border-radius: var(--radius-md);
  margin-bottom: 24px;
  width: 100%;
  max-height: 480px;
  object-fit: cover;
  aspect-ratio: 16/9;
  display: block;
}

body[style*="--show-featured-val: 2px"] .article-featured-img {
  display: none !important;
}

.has-featured-banner .article-body-content > .separator:first-child,
.has-featured-banner .article-body-content > div:first-child:has(img),
.has-featured-banner .article-body-content > p:first-child:has(img:only-child),
.article-wrapper:has(.article-featured-img) .article-body-content > .separator:first-child,
.article-wrapper:has(.article-featured-img) .article-body-content > div:first-child:has(img),
.article-wrapper:has(.article-featured-img) .article-body-content > p:first-child:has(img:only-child),
.article-body-content img[data-duplicate-featured="true"],
.article-body-content .separator[data-duplicate-featured="true"] {
  display: none !important;
}

.article-body-content {
  font-size: 1.08rem;
  line-height: 1.85;
  color: var(--text-color);
}

.article-body-content p {
  margin-bottom: 1.6rem;
}

.article-body-content h2, .article-body-content h3 {
  margin-top: 36px;
  margin-bottom: 16px;
  color: var(--text-color);
}

.article-body-content blockquote {
  background: var(--bg-color);
  border-right: 4px solid var(--primary-color);
  padding: 18px 24px;
  margin: 28px 0;
  border-radius: var(--radius-sm);
  font-style: italic;
}

.article-body-content pre, .article-body-content code {
  background: var(--bg-color);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-sm);
  padding: 14px;
  font-family: monospace;
  direction: ltr;
  text-align: left;
}

.article-tags-row {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
  margin-top: 18px;
}

.blog-pagination,
.blog-pager {
  display: flex;
  justify-content: center;
  align-items: center;
  margin-block-start: 40px;
  padding-block-start: 28px;
  border-block-start: 1px solid var(--border-color);
  width: 100%;
  box-sizing: border-box;
}

[style*="--enable-pagination: 2px"] .blog-pagination,
[style*="--enable-pagination: 2px"] .blog-pager {
  display: none !important;
}

.pagination-inner {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  flex-wrap: wrap;
  width: 100%;
}

.pagination-btn,
.pagination-num,
.blog-pager a {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 42px;
  height: 42px;
  padding-inline: 14px;
  background: var(--card-bg);
  border: 1px solid var(--border-color);
  color: var(--text-color);
  border-radius: var(--pagination-radius, var(--radius-sm, 8px));
  font-weight: 700;
  font-size: 0.9rem;
  text-decoration: none;
  box-sizing: border-box;
  transition: background-color 0.2s ease, border-color 0.2s ease, color 0.2s ease, transform 0.15s ease;
  user-select: none;
  -webkit-tap-highlight-color: transparent;
}

.pagination-num {
  padding-inline: 12px;
  min-width: 42px;
}

.pagination-btn {
  gap: 6px;
  padding-inline: 18px;
}

.pagination-btn.is-disabled,
.pagination-num.is-disabled {
  opacity: 0.4;
  cursor: not-allowed !important;
  pointer-events: none;
  background: var(--surfaceColor, #f8f9fa);
  border-color: var(--border-color);
  color: var(--muted-color);
  transform: none !important;
  box-shadow: none !important;
}

[data-theme="dark"] .pagination-btn.is-disabled,
[data-theme="dark"] .pagination-num.is-disabled {
  background: rgba(255, 255, 255, 0.03);
  border-color: rgba(255, 255, 255, 0.06);
  color: #64748b;
}

[style*="--enable-edit-post: 2px"] .edit-post-btn,
[style*="--enable-font-resizer: 2px"] .font-resizer-controls,
[style*="--enable-print-btn: 2px"] #printArticleBtn,
[style*="--enable-share-btns: 2px"] .pinfo-share-wrapper {
  display: none !important;
}

.pagination-btn:hover,
.pagination-num:hover,
.blog-pager a:hover {
  background: var(--surfaceColor, #f8f9fa);
  color: var(--primary-color);
  border-color: var(--primary-color);
  transform: translateY(-1px);
}

.pagination-num.is-active {
  background: var(--primary-color) !important;
  color: #ffffff !important;
  border-color: var(--primary-color) !important;
  cursor: default;
  transform: none !important;
  box-shadow: 0 2px 8px rgba(220, 31, 67, 0.25);
}

.pagination-numbers {
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

.pagination-ellipsis {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 28px;
  height: 42px;
  color: var(--muted-color);
  font-weight: 700;
  font-size: 1.1rem;
  user-select: none;
}

.pagination-arrow {
  display: inline-block;
  font-size: 1.2rem;
  line-height: 1;
  transition: transform 0.2s ease;
}

[dir="rtl"] .pagination-prev .pagination-arrow {
  transform: scaleX(-1);
}
[dir="rtl"] .pagination-next .pagination-arrow {
  transform: scaleX(-1);
}

.pagination-btn:hover .pagination-arrow {
  transform: translateX(-2px);
}
[dir="rtl"] .pagination-btn:hover .pagination-arrow {
  transform: scaleX(-1) translateX(-2px);
}
.pagination-next:hover .pagination-arrow {
  transform: translateX(2px);
}
[dir="rtl"] .pagination-next:hover .pagination-arrow {
  transform: scaleX(-1) translateX(2px);
}

.pagination-btn:focus-visible,
.pagination-num:focus-visible {
  outline: 2px solid var(--primary-color);
  outline-offset: 2px;
}

[style*="--pagination-show-prevnext: 2px"] .pagination-btn {
  display: none !important;
}

[data-theme="dark"] .pagination-btn,
[data-theme="dark"] .pagination-num,
[data-theme="dark"] .blog-pager a {
  background: var(--darkCardBg, #131722);
  border-color: rgba(255, 255, 255, 0.1);
  color: #e2e8f0;
}

[data-theme="dark"] .pagination-btn:hover,
[data-theme="dark"] .pagination-num:hover,
[data-theme="dark"] .blog-pager a:hover {
  background: rgba(255, 255, 255, 0.05);
  border-color: var(--primary-color);
  color: var(--primary-color);
}

[data-theme="dark"] .pagination-num.is-active {
  background: var(--primary-color) !important;
  color: #ffffff !important;
  border-color: var(--primary-color) !important;
}

@media (max-width: 600px) {
  .blog-pagination,
  .blog-pager {
    margin-block-start: 28px;
    padding-block-start: 20px;
  }
  .pagination-inner {
    gap: 5px;
  }
  .pagination-btn,
  .pagination-num,
  .blog-pager a {
    min-width: 38px;
    height: 38px;
    padding-inline: 10px;
    font-size: 0.85rem;
  }
  .pagination-btn .pagination-label {
    display: none;
  }
  .pagination-btn {
    padding-inline: 12px;
  }
}

.site-footer {
  background: var(--footer-bg, #1e293b);
  color: var(--footer-text, #9aa1ab);
