}

.footer-centered-wrap {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  max-width: 900px;
  margin: 0 auto;
  gap: 24px;
}

.footer-logo-wrap {
  margin-bottom: 6px;
  display: flex;
  justify-content: center;
  width: 100%;
}

.footer-logo-section {
  display: flex !important;
  justify-content: center !important;
  width: 100% !important;
}

.footer-wire-logo {
