  }
  .hero-main-card {
    height: 300px;
    min-height: 300px;
  }
  .hero-side-stack {
    height: auto;
  }
  .hero-sub-card {
    height: 180px;
    min-height: 180px;
  }
  .trending-grid {
    grid-template-columns: repeat(2, 1fr);
  }
  body {
    --sidebar-w: clamp(0px, calc((2 - max(var(--hide-sidebar-val, 1px), var(--hide-sidebar-mobile-val, 1px)) / 1px) * 100%), 100%);
  }
  .main-wrapper {
    flex-direction: column;
    gap: min(var(--main-gap), calc(var(--sidebar-w) * 999));
  }
  .sidebar {
    width: var(--sidebar-w);
    max-width: var(--sidebar-w);
  }
}

@media (max-width: 768px) {
  .site-header {
