  .share-action-btn {
    padding: 10px 14px;
    border-radius: 50%;
  }
}

.top-social-item {
  display: inline-flex !important;
  align-items: center !important;
  justify-content: center !important;
  width: 32px !important;
  height: 32px !important;
  border-radius: 50% !important;
  background: rgba(255, 255, 255, 0.08) !important;
  color: #ffffff !important;
}

.top-social-item svg {
  width: 15px !important;
  height: 15px !important;
  fill: currentColor !important;
  display: block !important;
}

.footer-social-btn {
  display: inline-flex !important;
  align-items: center !important;
  justify-content: center !important;
  width: 44px !important;
  height: 44px !important;
  border-radius: 50% !important;
  background: rgba(255, 255, 255, 0.08) !important;
  color: #ffffff !important;
}

.footer-social-btn svg {
  width: 18px !important;
  height: 18px !important;
  fill: currentColor !important;
  display: block !important;
}

.skip-to-content {
  position: absolute;
  top: -100px;
  right: 20px;
  background: var(--primary-color);
  color: #ffffff;
  padding: 10px 20px;
  border-radius: var(--radius-sm);
  font-weight: 700;
  z-index: 99999;
  text-decoration: none;
  transition: top 0.2s ease;
}
.skip-to-content:focus,
.skip-to-content:focus-visible {
  top: 15px;
  outline: 3px solid var(--accent-color);
  outline-offset: 2px;
}

.reading-progress-bar {
  position: fixed;
  top: 0;
  right: 0;
  left: 0;
  height: 4px;
  background: linear-gradient(90deg, var(--accent-color), var(--primary-color));
  width: 0%;
  z-index: 9999;
  transition: width 0.1s linear;
  box-shadow: 0 0 10px rgba(59, 130, 246, 0.4);
}

.article-series-box {
  margin: 20px 0 26px;
  padding: 16px 20px;
  background: rgba(37, 99, 235, 0.04);
  border-right: 4px solid var(--primary-color);
  border-radius: var(--radius-sm);
  border-top: 1px solid var(--border-color);
  border-bottom: 1px solid var(--border-color);
  border-left: 1px solid var(--border-color);
}
.series-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 8px;
  margin-bottom: 12px;
}
.series-badge {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  background: var(--primary-color);
  color: #ffffff;
  font-size: 0.75rem;
  font-weight: 700;
  padding: 3px 8px;
  border-radius: 4px;
}
.series-title {
  font-size: 1rem;
  font-weight: 700;
  color: var(--text-color);
  margin: 0;
  flex-grow: 1;
}
.series-step {
  font-size: 0.85rem;
  font-weight: 600;
  color: var(--muted-color);
}
.series-nav {
  display: flex;
  justify-content: space-between;
  gap: 12px;
}
.series-nav-btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 0.82rem;
  font-weight: 600;
  color: var(--primary-color);
  text-decoration: none;
  padding: 4px 8px;
  border-radius: var(--radius-sm);
  transition: background 0.2s ease;
}
.series-nav-btn:hover {
  background: rgba(37, 99, 235, 0.1);
}

.tekmax-toc-container {
  background: var(--card-bg, #f8fafc);
  border: 1px solid var(--border-color, #e2e8f0);
  border-radius: 8px;
  margin: 16px 0 24px;
  width: fit-content;
  min-width: 270px;
  max-width: 100%;
  box-sizing: border-box;
  font-family: inherit;
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.03);
  transition: border-color 0.2s ease, box-shadow 0.2s ease;
  overflow: hidden;
}

.tekmax-toc-container:hover {
  border-color: #cbd5e1;
}

.toc-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 7px 14px;
  cursor: pointer;
  user-select: none;
  background: transparent;
  min-height: 38px;
}

.toc-header-right {
  display: flex;
  align-items: center;
  gap: 8px;
}

.toc-toggle-btn {
  background: transparent;
  border: none;
  color: var(--text-color, #111827);
  cursor: pointer;
  padding: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  line-height: 1;
}

.toc-chevron {
  width: 16px;
  height: 16px;
  stroke: currentColor;
  stroke-width: 2.2;
  fill: none;
  stroke-linecap: round;
  stroke-linejoin: round;
  transition: transform 0.25s ease;
}

.tekmax-toc-container.collapsed .toc-chevron {
  transform: rotate(180deg);
}

.tekmax-toc-container .toc-title,
.toc-header h3 {
  margin: 0;
  padding: 0;
  font-size: 0.95rem;
  font-weight: 700;
  color: var(--text-color, #111827);
  line-height: 1.2;
}

.toc-header-left {
  display: flex;
  align-items: center;
}

.toc-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  color: var(--text-color, #111827);
  flex-shrink: 0;
}

.tekmax-toc-container.collapsed .toc-body {
  display: none;
}

.toc-body {
  padding: 4px 14px 12px;
  border-top: 1px solid rgba(0, 0, 0, 0.04);
}

.toc-list {
  list-style: none;
  padding: 0;
  margin: 0;
  display: flex;
  flex-direction: column;
  gap: 5px;
}

.toc-item {
  line-height: 1.45;
}

.toc-item.toc-level-3 {
  padding-right: 16px;
}

.toc-item.toc-level-4 {
  padding-right: 32px;
}

.toc-link {
  display: inline-flex;
  align-items: baseline;
  gap: 5px;
  color: var(--text-color, #1f2937);
  text-decoration: none;
  font-size: 0.9rem;
  font-weight: 600;
  transition: opacity 0.15s ease;
}

.toc-link:hover {
  opacity: 0.8;
}

.toc-num {
  color: #2563eb;
  font-weight: 700;
  font-size: 0.9rem;
  direction: ltr;
  display: inline-block;
  unicode-bidi: isolate;
  flex-shrink: 0;
}

.toc-text {
  color: var(--text-color, #1f2937);
  font-weight: 600;
}

[data-theme="dark"] .tekmax-toc-container {
  background: var(--card-bg, #171a20);
  border-color: var(--border-color, #242832);
}

[data-theme="dark"] .toc-num {
  color: #3b82f6;
}

[data-theme="dark"] .toc-text,
[data-theme="dark"] .toc-title,
[data-theme="dark"] .toc-icon,
[data-theme="dark"] .toc-toggle-btn {
  color: var(--text-color, #f2f4f7);
}

.tekmax-lightbox {
  position: fixed;
  inset: 0;
  z-index: 999999;
  display: flex;
  align-items: center;
  justify-content: center;
}
.lightbox-overlay {
  position: absolute;
  inset: 0;
  background: rgba(0, 0, 0, 0.88);
  -webkit-backdrop-filter: blur(8px);
  backdrop-filter: blur(8px);
}
.lightbox-content {
  position: relative;
  z-index: 2;
  max-width: 90vw;
  max-height: 90vh;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
}
.lightbox-img-wrap {
  overflow: hidden;
  display: flex;
  align-items: center;
  justify-content: center;
  max-width: 88vw;
  max-height: 82vh;
}
.lightbox-img {
  max-width: 100%;
  max-height: 82vh;
  object-fit: contain;
  border-radius: var(--radius-sm);
  box-shadow: 0 10px 40px rgba(0, 0, 0, 0.8);
  transition: transform 0.25s ease;
  user-select: none;
}
.lightbox-img.zoomed {
  transform: scale(1.6);
  cursor: grab;
}
.lightbox-btn {
  position: absolute;
  background: rgba(255, 255, 255, 0.15);
  border: 1px solid rgba(255, 255, 255, 0.2);
  color: #ffffff;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 50%;
  transition: background-color 0.2s ease, border-color 0.2s ease;
  z-index: 10;
}
.lightbox-btn:hover, .lightbox-btn:focus-visible {
  background: var(--primary-color);
  border-color: var(--primary-color);
  outline: none;
}
.lightbox-close {
  top: -45px;
  left: 0;
  width: 36px;
  height: 36px;
}
.lightbox-zoom {
  top: -45px;
  left: 48px;
  width: 36px;
  height: 36px;
}
.lightbox-prev {
  right: -55px;
  top: 50%;
  transform: translateY(-50%);
  width: 44px;
  height: 44px;
}
.lightbox-next {
  left: -55px;
  top: 50%;
  transform: translateY(-50%);
  width: 44px;
  height: 44px;
}
.lightbox-counter {
  margin-top: 12px;
  color: #ffffff;
  font-size: 0.85rem;
  font-weight: 700;
  background: rgba(0, 0, 0, 0.6);
  padding: 4px 12px;
  border-radius: 20px;
}

@media (max-width: 768px) {
  .lightbox-prev {
    right: 5px;
    background: rgba(0, 0, 0, 0.5);
  }
  .lightbox-next {
    left: 5px;
    background: rgba(0, 0, 0, 0.5);
  }
  .lightbox-close {
    top: -40px;
    left: 5px;
  }
  .lightbox-zoom {
    display: none;
  }
}

.article-author-box {
  display: flex;
  gap: 20px;
  padding: 24px;
  margin: 32px 0 24px;
  background: var(--card-bg);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  align-items: flex-start;
  box-shadow: var(--shadow-subtle);
}
.author-avatar-wrap {
  flex-shrink: 0;
}
.author-avatar-img {
  width: 74px;
  height: 74px;
  border-radius: 50%;
  object-fit: cover;
  aspect-ratio: 1/1;
  border: 3px solid var(--border-color);
}
.author-avatar-placeholder {
  width: 74px;
  height: 74px;
  border-radius: 50%;
  background: var(--border-color);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--muted-color);
}
.author-info {
  flex-grow: 1;
  min-width: 0;
}
.author-meta-top {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 6px;
  flex-wrap: wrap;
}
.author-role-badge {
  font-size: 0.72rem;
  font-weight: 700;
  background: rgba(37, 99, 235, 0.1);
  color: var(--primary-color);
  padding: 2px 8px;
  border-radius: 4px;
}
.author-name {
  font-size: 1.15rem;
  font-weight: 800;
  margin: 0;
}
.author-name a {
  color: var(--text-color);
  text-decoration: none;
  transition: color 0.2s ease;
}
.author-name a:hover {
  color: var(--primary-color);
}
.author-bio {
  font-size: 0.92rem;
  line-height: 1.6;
  color: var(--muted-color);
  margin: 6px 0 12px;
}
.author-social-links {
  display: flex;
  gap: 8px;
}
.author-social-links a {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 32px;
  height: 32px;
  border-radius: 50%;
  background: var(--border-color);
  color: var(--text-color);
  transition: color 0.2s ease, background-color 0.2s ease;
  text-decoration: none;
}
.author-social-links a:hover {
  background: var(--primary-color);
  color: #ffffff;
}

@media (max-width: 600px) {
  .article-author-box {
    flex-direction: column;
    align-items: center;
    text-align: center;
  }
  .author-meta-top {
    justify-content: center;
  }
  .author-social-links {
    justify-content: center;
  }
}

.related-posts-section {
  margin: 36px 0 28px;
}
.related-posts-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
  margin-top: 16px;
}
.related-post-card {
  background: var(--card-bg);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  overflow: hidden;
  transition: transform 0.2s ease, box-shadow 0.2s ease;
  display: flex;
  flex-direction: column;
}
.related-post-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-card);
}
.related-thumb-wrap {
  position: relative;
  width: 100%;
  aspect-ratio: 16/10;
  overflow: hidden;
  background: var(--border-color);
}
.related-thumb {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 0.35s ease;
}
.related-post-card:hover .related-thumb {
  transform: scale(1.05);
}
.related-content {
  padding: 14px;
  display: flex;
  flex-direction: column;
  flex-grow: 1;
}
.related-date {
  font-size: 0.78rem;
  color: var(--muted-color);
  margin-bottom: 6px;
}
.related-title {
  font-size: 0.95rem;
  font-weight: 700;
  line-height: 1.45;
  margin: 0;
}
.related-title a {
  color: var(--text-color);
  text-decoration: none;
  transition: color 0.2s ease;
}
.related-title a:hover {
  color: var(--primary-color);
}

@media (max-width: 900px) {
  .related-posts-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}
@media (max-width: 600px) {
  .related-posts-grid {
    grid-template-columns: 1fr;
  }
}

:focus-visible {
  outline: 2px solid var(--primary-color);
  outline-offset: 2px;
}

@media (prefers-reduced-motion: reduce) {
  *, ::before, ::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}

@media print {
  body {
    background: #ffffff !important;
    color: #000000 !important;
    font-size: 12pt;
    line-height: 1.5;
  }
  .top-bar, .site-header, .nav-menu-section, .sidebar, .site-footer,
  .article-tools-bar, .pinfo-header-actions, .reading-progress-bar, .tekmax-toc-container,
  .article-share-strip, .related-posts-section, .comments-wrap,
  .tm-ad-slot, .code-copy-btn, .mobile-toggle, .lightbox-overlay, .tekmax-lightbox {
    display: none !important;
  }
  .main-wrapper {
    max-width: 100% !important;
    margin: 0 !important;
    padding: 0 !important;
  }
  .main-content {
    width: 100% !important;
  }
  .article-wrapper {
    border: none !important;
    padding: 0 !important;
    box-shadow: none !important;
  }
  .article-headline {
    color: #000000 !important;
    font-size: 24pt !important;
    margin-bottom: 10pt !important;
  }
  .article-body-content {
    color: #111111 !important;
  }
  .article-body-content a {
    color: #000000 !important;
    text-decoration: underline !important;
  }
  .code-block-wrapper {
    border: 1px solid #cccccc !important;
    background: #f9f9f9 !important;
  }
  .code-block-wrapper pre {
    color: #000000 !important;
  }
}

.code-block-wrapper,
.gh-code-box {
  position: relative;
  margin: 26px 0;
  background: #f6f8fa;
  border: 1px solid #d0d7de;
  border-radius: var(--radius-md, 8px);
  overflow: hidden;
  direction: ltr !important;
  text-align: left !important;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.04);
  transition: border-color 0.2s ease, box-shadow 0.2s ease;
}

[data-theme="dark"] .code-block-wrapper,
[data-theme="dark"] .gh-code-box {
  background: #0d1117;
  border-color: #30363d;
  box-shadow: 0 4px 20px rgba(0, 0, 0, 0.35);
}

.code-block-header,
.gh-code-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 8px 14px;
  background: #f6f8fa;
  border-bottom: 1px solid #d0d7de;
  font-family: ui-monospace, SFMono-Regular, "SF Mono", Menlo, Consolas, monospace;
  font-size: 0.78rem;
  color: #57606a;
  user-select: none;
}

[data-theme="dark"] .code-block-header,
[data-theme="dark"] .gh-code-header {
  background: #161b22;
  border-bottom-color: #30363d;
  color: #8b949e;
}

.gh-header-left {
  display: inline-flex;
  align-items: center;
  gap: 10px;
}

.gh-mac-dots {
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

.gh-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  display: inline-block;
}

.gh-dot-red { background: #ff5f56; }
.gh-dot-yellow { background: #ffbd2e; }
.gh-dot-green { background: #27c93f; }

.code-lang-tag,
.gh-lang-tag {
  font-weight: 700;
  font-size: 0.76rem;
  color: #57606a;
  letter-spacing: 0.5px;
  display: inline-flex;
  align-items: center;
  gap: 4px;
}

[data-theme="dark"] .code-lang-tag,
[data-theme="dark"] .gh-lang-tag {
  color: #8b949e;
}

.code-copy-btn,
.gh-copy-btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  background: #ffffff;
  border: 1px solid #d0d7de;
  color: #24292f;
  padding: 4px 10px;
  border-radius: 6px;
  font-size: 0.75rem;
  font-weight: 600;
  cursor: pointer;
  transition: color 0.2s ease, background-color 0.2s ease, border-color 0.2s ease;
  direction: rtl;
  font-family: inherit;
}

[data-theme="dark"] .code-copy-btn,
[data-theme="dark"] .gh-copy-btn {
  background: #21262d;
  border-color: #30363d;
  color: #c9d1d9;
}

.code-copy-btn:hover,
.gh-copy-btn:hover {
  background: #f3f4f6;
  border-color: #1b1f24;
  color: #0969da;
}

[data-theme="dark"] .code-copy-btn:hover,
[data-theme="dark"] .gh-copy-btn:hover {
  background: #30363d;
  border-color: #8b949e;
  color: #58a6ff;
}

.code-copy-btn.copied,
.gh-copy-btn.copied {
  background: #1f883d !important;
  border-color: #1f883d !important;
  color: #ffffff !important;
}

.hide-copy-code .code-copy-btn,
.hide-copy-code .gh-copy-btn {
  display: none !important;
}

.gh-code-body {
  display: flex;
  position: relative;
  overflow-x: auto;
  -webkit-overflow-scrolling: touch;
  font-family: ui-monospace, SFMono-Regular, "SF Mono", Menlo, Consolas, "Liberation Mono", monospace !important;
  font-size: 13.5px;
  line-height: 1.6;
}

.gh-line-numbers {
  display: flex;
  flex-direction: column;
  padding: 14px 10px;
  text-align: right;
  user-select: none;
  flex-shrink: 0;
  color: #8c959f;
  border-right: 1px solid #d0d7de;
  font-size: 13px;
  line-height: 1.6;
  min-width: 28px;
  background: rgba(0, 0, 0, 0.015);
}

[data-theme="dark"] .gh-line-numbers {
  color: #6e7681;
  border-right-color: #30363d;
  background: rgba(255, 255, 255, 0.015);
}

.gh-pre,
.code-block-wrapper pre {
  margin: 0 !important;
  padding: 14px 18px !important;
  background: transparent !important;
  border: none !important;
  overflow-x: auto;
  -webkit-overflow-scrolling: touch;
  flex-grow: 1;
  color: #24292f;
  font-family: inherit !important;
  font-size: inherit !important;
  line-height: inherit !important;
  tab-size: 4;
}

[data-theme="dark"] .gh-pre,
[data-theme="dark"] .code-block-wrapper pre {
  color: #e6edf3;
}

.gh-code,
.code-block-wrapper code {
  font-family: inherit !important;
  font-size: inherit !important;
  color: inherit !important;
  background: transparent !important;
  padding: 0 !important;
  border: none !important;
  white-space: pre !important;
}

.tok-kw { color: #cf222e; font-weight: 600; }
.tok-str { color: #0a3069; }
.tok-comm { color: #6e7781; font-style: italic; }
.tok-num { color: #0550ae; }
.tok-tag { color: #116329; font-weight: 600; }
.tok-attr { color: #0550ae; }
.tok-prop { color: #953800; }
.tok-func { color: #8250df; font-weight: 600; }
.tok-blogger { color: #dc1f43; font-weight: 700; }

[data-theme="dark"] .tok-kw { color: #ff7b72; font-weight: 600; }
[data-theme="dark"] .tok-str { color: #a5d6ff; }
[data-theme="dark"] .tok-comm { color: #8b949e; font-style: italic; }
[data-theme="dark"] .tok-num { color: #79c0ff; }
[data-theme="dark"] .tok-tag { color: #7ee787; font-weight: 600; }
[data-theme="dark"] .tok-attr { color: #79c0ff; }
[data-theme="dark"] .tok-prop { color: #ffa657; }
[data-theme="dark"] .tok-func { color: #d2a8ff; font-weight: 600; }
[data-theme="dark"] .tok-blogger { color: #ff4d6d; font-weight: 700; }

.post-info-box {
  margin: 22px 0 28px;
  padding: 18px 20px;
  background: var(--card-bg, #f8f9fa);
  border: 1px solid var(--border-color, #eaedf1);
  border-radius: var(--radius-md, 12px);
  box-shadow: var(--shadow-subtle, 0 2px 8px rgba(0, 0, 0, 0.04));
  transition: background-color 0.25s ease, border-color 0.25s ease, box-shadow 0.25s ease;
}

[data-theme="dark"] .post-info-box {
  background: #171a20;
  border-color: #242832;
}

.post-info-box-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 12px;
  margin-bottom: 16px;
  padding-bottom: 12px;
  border-bottom: 1px dashed var(--border-color, #eaedf1);
}

[data-theme="dark"] .post-info-box-header {
  border-bottom-color: #242832;
}

.pinfo-header-start {
  display: flex;
  align-items: center;
}

.post-info-box-title {
  font-size: 0.95rem;
  font-weight: 800;
  color: var(--text-color, #111317);
  display: flex;
  align-items: center;
  gap: 8px;
  margin: 0;
  font-family: var(--heading-font, 'Cairo', sans-serif);
}

.pinfo-title-icon {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 28px;
  height: 28px;
  border-radius: 6px;
  background: rgba(220, 31, 67, 0.08);
  color: var(--primary-color, #dc1f43);
}

.pinfo-header-actions {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}

.font-resizer-controls {
  display: inline-flex;
  align-items: center;
  border: 1px solid var(--border-color, #eaedf1);
  border-radius: 8px;
  background: var(--bg-color, #ffffff);
  overflow: hidden;
  height: 32px;
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.03);
}

[data-theme="dark"] .font-resizer-controls {
  background: #14171d;
  border-color: #242832;
}

.resizer-btn {
  background: transparent;
  border: none;
  border-left: 1px solid var(--border-color, #eaedf1);
  padding: 0 10px;
  height: 100%;
  font-size: 0.82rem;
  font-weight: 700;
  color: var(--text-color, #111317);
  cursor: pointer;
  transition: color 0.2s ease, background-color 0.2s ease;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  line-height: 1;
}

[data-theme="dark"] .resizer-btn {
  border-left-color: #242832;
  color: #e2e8f0;
}

.resizer-btn:first-child {
  border-left: none;
}

.resizer-btn:hover, .resizer-btn:focus-visible {
  background: var(--primary-color, #dc1f43);
  color: #ffffff;
  outline: none;
}

.resizer-btn:active {
  transform: scale(0.95);
}

.tool-action-btn {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  padding: 0 14px;
  height: 32px;
  border-radius: 8px;
  font-size: 0.80rem;
  font-weight: 700;
  color: #ffffff !important;
  cursor: pointer;
  transition: color 0.25s cubic-bezier(0.16, 1, 0.3, 1), background-color 0.25s cubic-bezier(0.16, 1, 0.3, 1), border-color 0.25s cubic-bezier(0.16, 1, 0.3, 1), transform 0.25s cubic-bezier(0.16, 1, 0.3, 1), box-shadow 0.25s cubic-bezier(0.16, 1, 0.3, 1);
  text-decoration: none !important;
  white-space: nowrap;
  border: 1px solid transparent;
}

.tool-action-btn svg {
  flex-shrink: 0;
  color: #ffffff;
  stroke: #ffffff;
  transition: transform 0.25s ease;
}

.tool-action-btn.edit-post-btn {
  background: var(--primary-color, #dc1f43);
  border-color: var(--primary-color, #dc1f43);
  box-shadow: 0 2px 8px rgba(220, 31, 67, 0.25);
}

.tool-action-btn.edit-post-btn:hover,
.tool-action-btn.edit-post-btn:focus-visible {
  background: var(--accent-color, #ff244d);
  border-color: var(--accent-color, #ff244d);
  color: #ffffff !important;
  transform: translateY(-2px);
  box-shadow: 0 6px 18px rgba(220, 31, 67, 0.42);
  outline: none;
}

.tool-action-btn.edit-post-btn:hover svg {
  transform: rotate(-12deg) scale(1.15);
}

.tool-action-btn.pinfo-share-btn {
  background: #2563eb;
  border-color: #2563eb;
  box-shadow: 0 2px 8px rgba(37, 99, 235, 0.25);
}

.tool-action-btn.pinfo-share-btn:hover,
.tool-action-btn.pinfo-share-btn:focus-visible {
  background: #1d4ed8;
  border-color: #1d4ed8;
  color: #ffffff !important;
  transform: translateY(-2px);
  box-shadow: 0 6px 18px rgba(37, 99, 235, 0.42);
  outline: none;
}

.tool-action-btn.pinfo-share-btn:hover svg {
  transform: scale(1.15) rotate(10deg);
}

.tool-action-btn:active {
  transform: translateY(0) scale(0.98);
  box-shadow: 0 1px 4px rgba(0, 0, 0, 0.2);
}

[data-theme="dark"] .tool-action-btn.edit-post-btn {
  background: var(--primary-color, #dc1f43);
  border-color: var(--primary-color, #dc1f43);
  box-shadow: 0 2px 8px rgba(220, 31, 67, 0.35);
}

[data-theme="dark"] .tool-action-btn.edit-post-btn:hover {
  background: var(--accent-color, #ff244d);
  box-shadow: 0 6px 18px rgba(220, 31, 67, 0.55);
}

[data-theme="dark"] .tool-action-btn.pinfo-share-btn {
  background: #2563eb;
  border-color: #2563eb;
  box-shadow: 0 2px 8px rgba(37, 99, 235, 0.35);
}

[data-theme="dark"] .tool-action-btn.pinfo-share-btn:hover {
  background: #3b82f6;
  border-color: #3b82f6;
  box-shadow: 0 6px 18px rgba(59, 130, 246, 0.55);
}

.pinfo-share-wrapper {
  position: relative;
  display: inline-flex;
}

.pinfo-share-menu {
  position: absolute;
  top: calc(100% + 6px);
  left: 0;
  z-index: 100;
  min-width: 155px;
  background: var(--bg-color, #ffffff);
  border: 1px solid var(--border-color, #eaedf1);
  border-radius: 10px;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.12);
  padding: 6px;
  display: none;
  flex-direction: column;
  gap: 2px;
  animation: pinfoFadeIn 0.2s cubic-bezier(0.16, 1, 0.3, 1);
}

[data-theme="dark"] .pinfo-share-menu {
  background: #171a20;
  border-color: #242832;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.4);
}

@keyframes pinfoFadeIn {
  from { opacity: 0; transform: translateY(-4px); }
  to { opacity: 1; transform: translateY(0); }
}

.pinfo-share-item {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 7px 10px;
  border-radius: 6px;
  font-size: 0.80rem;
  font-weight: 600;
  color: var(--text-color, #111317);
  text-decoration: none !important;
  background: transparent;
  border: none;
  width: 100%;
  cursor: pointer;
  transition: color 0.15s ease, background-color 0.15s ease;
  text-align: right;
  box-sizing: border-box;
}

[data-theme="dark"] .pinfo-share-item {
  color: #e2e8f0;
}

.pinfo-share-item:hover {
  background: rgba(220, 31, 67, 0.08);
  color: var(--primary-color, #dc1f43);
}

.pinfo-share-item svg {
  flex-shrink: 0;
}

.pinfo-share-item.pinfo-share-tw:hover { color: #000000; background: #f0f0f0; }
[data-theme="dark"] .pinfo-share-item.pinfo-share-tw:hover { color: #ffffff; background: #242832; }
.pinfo-share-item.pinfo-share-fb:hover { color: #1877f2; background: rgba(24, 119, 242, 0.08); }
.pinfo-share-item.pinfo-share-wa:hover { color: #25d366; background: rgba(37, 211, 102, 0.08); }
.pinfo-share-item.pinfo-share-tg:hover { color: #229ed9; background: rgba(34, 158, 217, 0.08); }
.pinfo-share-item.pinfo-share-copy:hover { color: var(--primary-color, #dc1f43); background: rgba(220, 31, 67, 0.08); }

@media (max-width: 640px) {
  .post-info-box-header {
    flex-direction: column;
    align-items: flex-start;
    gap: 12px;
  }
  .pinfo-header-actions {
    width: 100%;
    justify-content: flex-start;
    gap: 6px;
  }
  .pinfo-header-actions .tool-action-btn {
    padding: 0 9px;
    font-size: 0.76rem;
  }
}

.pinfo-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(170px, 1fr));
  gap: 12px;
}

.pinfo-card {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 8px 12px;
  background: var(--bg-color, #ffffff);
  border: 1px solid var(--border-color, #eaedf1);
  border-radius: 8px;
  font-size: 0.82rem;
  transition: transform 0.2s ease, border-color 0.2s ease;
}

[data-theme="dark"] .pinfo-card {
  background: #14171d;
  border-color: #242832;
}

.pinfo-card:hover {
  border-color: var(--primary-color, #dc1f43);
  transform: translateY(-1px);
}

.pinfo-card.pinfo-print {
  cursor: pointer;
  user-select: none;
}

.pinfo-card.pinfo-print:hover .pinfo-val {
  color: var(--primary-color, #dc1f43);
}

.pinfo-card.pinfo-print:active {
  transform: translateY(0);
}

.pinfo-icon {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 32px;
  height: 32px;
  border-radius: 50%;
  background: rgba(220, 31, 67, 0.08);
  color: var(--primary-color, #dc1f43);
  flex-shrink: 0;
}

.pinfo-content {
  display: flex;
  flex-direction: column;
  min-width: 0;
}

.pinfo-label {
  font-size: 0.72rem;
  color: var(--muted-color, #555d6b);
  font-weight: 600;
}

.pinfo-val {
  font-size: 0.84rem;
  font-weight: 700;
  color: var(--text-color, #111317);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.pinfo-val a {
  color: inherit;
  transition: color 0.2s ease;
}

.pinfo-val a:hover {
  color: var(--primary-color, #dc1f43);
}

.hide-post-info .post-info-box,
html.hide-post-info .post-info-box,
body.hide-post-info .post-info-box,
.hide-post-info #postInfoBox,
html.hide-post-info #postInfoBox {
  display: none !important;
}

.hide-post-author .pinfo-author,
html.hide-post-author .pinfo-author,
body.hide-post-author .pinfo-author {
  display: none !important;
}

.hide-publish-date .pinfo-published,
html.hide-publish-date .pinfo-published,
body.hide-publish-date .pinfo-published {
  display: none !important;
}

.hide-updated-date .pinfo-updated,
html.hide-updated-date .pinfo-updated,
body.hide-updated-date .pinfo-updated {
  display: none !important;
}

.hide-post-category .pinfo-category,
html.hide-post-category .pinfo-category,
body.hide-post-category .pinfo-category {
  display: none !important;
}

.hide-comment-count .pinfo-comments,
html.hide-comment-count .pinfo-comments,
body.hide-comment-count .pinfo-comments {
  display: none !important;
}

.header-follow-sec {
  display: inline-flex;
  align-items: center;
  margin: 0;
  padding: 0;
}

.follow-site-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  background: var(--primary-color, #dc1f43);
  color: #ffffff !important;
  padding: 7px 16px;
  min-height: 36px;
  box-sizing: border-box;
  border-radius: 50px;
  font-size: 0.84rem;
  font-weight: 700;
  line-height: 1;
  text-align: center;
  text-decoration: none !important;
  box-shadow: 0 3px 10px rgba(220, 31, 67, 0.25);
  transition: background-color 0.25s cubic-bezier(0.16, 1, 0.3, 1), transform 0.25s cubic-bezier(0.16, 1, 0.3, 1), box-shadow 0.25s cubic-bezier(0.16, 1, 0.3, 1);
  cursor: pointer;
  border: none;
  white-space: nowrap;
  vertical-align: middle;
}

.follow-site-btn:hover {
  background: var(--accent-color, #ff244d);
  transform: translateY(-2px);
  box-shadow: 0 5px 15px rgba(220, 31, 67, 0.35);
  color: #ffffff !important;
}

.follow-site-btn svg {
  width: 15px;
  height: 15px;
  fill: #ffffff;
  flex-shrink: 0;
  display: block;
}

.follow-site-btn span {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  line-height: 1;
  transform: translateY(-0.5px);
}

.pinfo-follow-btn {
  display: none; 
  background: rgba(220, 31, 67, 0.08);
  color: var(--primary-color, #dc1f43) !important;
  border: 1px solid rgba(220, 31, 67, 0.25);
  padding: 5px 12px;
  border-radius: 6px;
  font-size: 0.78rem;
  font-weight: 700;
  box-shadow: none;
}

.pinfo-follow-btn:hover {
  background: var(--primary-color, #dc1f43);
  color: #ffffff !important;
  border-color: var(--primary-color, #dc1f43);
  box-shadow: 0 3px 10px rgba(220, 31, 67, 0.25);
}

.floating-follow-btn {
  display: none; 
  position: fixed;
  bottom: 82px;
  left: 28px;
  z-index: 9990;
  padding: 10px 18px;
  font-size: 0.88rem;
  font-weight: 800;
  background: linear-gradient(135deg, var(--primary-color, #dc1f43) 0%, #b81434 100%);
  color: #ffffff !important;
  border: 1px solid rgba(255, 255, 255, 0.25);
  border-radius: 50px;
  box-shadow: 0 8px 24px rgba(220, 31, 67, 0.4), 0 2px 6px rgba(0, 0, 0, 0.15);
}

.floating-follow-btn:hover {
  transform: translateY(-3px) scale(1.02);
  box-shadow: 0 12px 30px rgba(220, 31, 67, 0.5);
  background: var(--accent-color, #ff244d);
  color: #ffffff !important;
}

@media (max-width: 768px) {
  .floating-follow-btn {
    bottom: 70px;
    left: 20px;
    padding: 8px 14px;
    font-size: 0.8rem;
  }
}

#headerFollowBtn { display: inline-flex; }
#articleFollowBtn { display: none !important; }
#floatingFollowBtn { display: none !important; }

html.follow-btn-article #headerFollowBtn,
body.follow-btn-article #headerFollowBtn {
  display: none !important;
}
html.follow-btn-article #articleFollowBtn,
body.follow-btn-article #articleFollowBtn,
html.follow-btn-article .pinfo-follow-btn,
body.follow-btn-article .pinfo-follow-btn {
  display: inline-flex !important;
}
html.follow-btn-article #floatingFollowBtn,
body.follow-btn-article #floatingFollowBtn {
  display: none !important;
}

html.follow-btn-floating #headerFollowBtn,
body.follow-btn-floating #headerFollowBtn {
  display: none !important;
}
html.follow-btn-floating #articleFollowBtn,
body.follow-btn-floating #articleFollowBtn {
  display: none !important;
}
html.follow-btn-floating #floatingFollowBtn,
body.follow-btn-floating #floatingFollowBtn,
html.follow-btn-floating .floating-follow-btn,
body.follow-btn-floating .floating-follow-btn {
  display: inline-flex !important;
}

.hide-follow-btn .follow-site-btn,
html.hide-follow-btn .follow-site-btn,
body.hide-follow-btn .follow-site-btn,
.hide-follow-btn #headerFollowBtn,
html.hide-follow-btn #headerFollowBtn,
.hide-follow-btn #articleFollowBtn,
html.hide-follow-btn #articleFollowBtn,
.hide-follow-btn #floatingFollowBtn,
html.hide-follow-btn #floatingFollowBtn,
.hide-follow-btn .floating-follow-btn,
html.hide-follow-btn .floating-follow-btn {
  display: none !important;
}

.smart-404-container {
  max-width: 820px;
  margin: 30px auto 60px;
  padding: 0 20px;
  text-align: center;
}

.smart-404-hero {
  padding: 36px 24px;
  background: var(--card-bg, #f8f9fa);
  border: 1px solid var(--border-color, #eaedf1);
  border-radius: var(--radius-lg, 16px);
  box-shadow: var(--shadow-card, 0 4px 16px rgba(0, 0, 0, 0.06));
  margin-bottom: 32px;
}

[data-theme="dark"] .smart-404-hero {
  background: #171a20;
  border-color: #242832;
}

.smart-404-code {
  font-size: clamp(4rem, 10vw, 7rem);
  font-weight: 900;
  line-height: 1;
  background: linear-gradient(135deg, var(--primary-color, #dc1f43), var(--accent-color, #ff244d));
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  font-family: var(--heading-font, 'Cairo', sans-serif);
  margin-bottom: 12px;
}

.smart-404-title {
  font-size: clamp(1.3rem, 3vw, 1.8rem);
  font-weight: 800;
  color: var(--text-color, #111317);
  margin-bottom: 10px;
}

.smart-404-desc {
  font-size: 0.96rem;
  color: var(--muted-color, #555d6b);
  max-width: 520px;
  margin: 0 auto 24px;
  line-height: 1.6;
}

.smart-404-search {
  max-width: 480px;
  margin: 0 auto 20px;
}

.smart-404-actions {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  flex-wrap: wrap;
}

.smart-404-home-btn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: var(--primary-color, #dc1f43);
  color: #ffffff !important;
  padding: 10px 22px;
  border-radius: 8px;
  font-weight: 700;
  font-size: 0.9rem;
  text-decoration: none !important;
  transition: background-color 0.25s ease, transform 0.25s ease, box-shadow 0.25s ease;
}

.smart-404-home-btn:hover {
  background: var(--accent-color, #ff244d);
  transform: translateY(-2px);
  box-shadow: 0 6px 18px rgba(220, 31, 67, 0.35);
}

.smart-404-suggestions {
  margin-top: 36px;
  text-align: right;
}

.smart-404-sec-heading {
  font-size: 1.2rem;
  font-weight: 800;
  color: var(--text-color, #111317);
  margin-bottom: 16px;
  display: flex;
  align-items: center;
  gap: 8px;
  border-bottom: 2px solid var(--border-color, #eaedf1);
  padding-bottom: 8px;
}

.smart-404-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
  gap: 16px;
}

.smart-404-card {
  display: flex;
  flex-direction: column;
  background: var(--card-bg, #f8f9fa);
  border: 1px solid var(--border-color, #eaedf1);
  border-radius: 10px;
  overflow: hidden;
  text-decoration: none !important;
  transition: border-color 0.25s ease, transform 0.25s ease, box-shadow 0.25s ease;
}

[data-theme="dark"] .smart-404-card {
  background: #171a20;
  border-color: #242832;
}

.smart-404-card:hover {
  border-color: var(--primary-color, #dc1f43);
  transform: translateY(-3px);
  box-shadow: var(--shadow-hover, 0 8px 24px rgba(0, 0, 0, 0.1));
}

.smart-404-card-img {
  width: 100%;
  aspect-ratio: 16 / 9;
  object-fit: cover;
  background: #1e2229;
}

.smart-404-card-content {
  padding: 12px 14px;
  display: flex;
  flex-direction: column;
  flex: 1;
}

.smart-404-card-title {
  font-size: 0.9rem;
  font-weight: 700;
  color: var(--text-color, #111317);
  line-height: 1.4;
  margin-bottom: 8px;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.smart-404-card-meta {
  font-size: 0.74rem;
  color: var(--muted-color, #555d6b);
  margin-top: auto;
}

.advanced-archive-app {
  max-width: 900px;
  margin: 30px auto;
  padding: 0 16px;
}

.archive-hero-box {
  padding: 26px;
  background: var(--card-bg, #f8f9fa);
  border: 1px solid var(--border-color, #eaedf1);
  border-radius: var(--radius-lg, 16px);
  margin-bottom: 24px;
}

[data-theme="dark"] .archive-hero-box {
  background: #171a20;
  border-color: #242832;
}

.archive-hero-title {
  font-size: 1.5rem;
  font-weight: 800;
  color: var(--text-color, #111317);
  margin-bottom: 8px;
  display: flex;
  align-items: center;
  gap: 10px;
}

.archive-hero-title svg {
  color: var(--primary-color, #dc1f43);
}

.archive-hero-desc {
  font-size: 0.92rem;
  color: var(--muted-color, #555d6b);
  margin-bottom: 18px;
}

.archive-toolbar {
  display: flex;
  align-items: center;
  gap: 12px;
  flex-wrap: wrap;
}

.archive-search-box {
  flex: 1;
  min-width: 220px;
  position: relative;
}

.archive-search-input {
  width: 100%;
  height: 42px;
  padding: 0 16px 0 42px;
  background: var(--bg-color, #ffffff);
  border: 1px solid var(--border-color, #eaedf1);
  border-radius: 8px;
  font-size: 0.88rem;
  font-family: inherit;
  color: var(--text-color, #111317);
  outline: none;
  transition: border-color 0.2s ease;
}

[data-theme="dark"] .archive-search-input {
  background: #14171d;
  border-color: #242832;
}

.archive-search-input:focus {
  border-color: var(--primary-color, #dc1f43);
}

.archive-search-icon {
  position: absolute;
  left: 14px;
  top: 50%;
  transform: translateY(-50%);
  color: var(--muted-color, #555d6b);
  pointer-events: none;
}

.archive-year-select {
  height: 42px;
  padding: 0 14px;
  background: var(--bg-color, #ffffff);
  border: 1px solid var(--border-color, #eaedf1);
  border-radius: 8px;
  font-size: 0.88rem;
  font-family: inherit;
  color: var(--text-color, #111317);
  outline: none;
  cursor: pointer;
}

[data-theme="dark"] .archive-year-select {
  background: #14171d;
  border-color: #242832;
}

.archive-tree-container {
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.archive-year-group {
  border: 1px solid var(--border-color, #eaedf1);
  border-radius: 12px;
  background: var(--card-bg, #f8f9fa);
  overflow: hidden;
}

[data-theme="dark"] .archive-year-group {
  background: #171a20;
  border-color: #242832;
}

.archive-year-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 14px 18px;
  background: rgba(0, 0, 0, 0.02);
  cursor: pointer;
  user-select: none;
  font-weight: 800;
  font-size: 1.1rem;
  color: var(--text-color, #111317);
}

[data-theme="dark"] .archive-year-header {
  background: rgba(255, 255, 255, 0.02);
}

.archive-year-count-badge {
  background: var(--primary-color, #dc1f43);
  color: #ffffff;
  padding: 2px 10px;
  border-radius: 20px;
  font-size: 0.76rem;
  font-weight: 700;
}

.archive-months-wrap {
  padding: 8px 16px 16px;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.archive-month-block {
  border: 1px solid var(--border-color, #eaedf1);
  border-radius: 8px;
  background: var(--bg-color, #ffffff);
  overflow: hidden;
}

[data-theme="dark"] .archive-month-block {
  background: #14171d;
  border-color: #242832;
}

.archive-month-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 14px;
  cursor: pointer;
  user-select: none;
  font-weight: 700;
  font-size: 0.92rem;
  color: var(--text-color, #111317);
}

.archive-month-header:hover {
  color: var(--primary-color, #dc1f43);
}

.archive-posts-list {
  list-style: none;
  margin: 0;
  padding: 4px 14px 10px;
  display: flex;
  flex-direction: column;
  gap: 6px;
  border-top: 1px dashed var(--border-color, #eaedf1);
}

.archive-post-link {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 6px 8px;
  border-radius: 6px;
  color: var(--text-color, #111317);
  text-decoration: none;
  font-size: 0.86rem;
  transition: color 0.2s ease, background-color 0.2s ease, transform 0.2s ease;
}

.archive-post-link:hover {
  background: rgba(220, 31, 67, 0.06);
  color: var(--primary-color, #dc1f43);
  transform: translateX(-4px);
}

.archive-post-date {
  font-size: 0.74rem;
  color: var(--muted-color, #555d6b);
  white-space: nowrap;
}

.archive-state-box {
  padding: 40px 20px;
  text-align: center;
  color: var(--muted-color, #555d6b);
  font-size: 0.95rem;
}

.archive-spinner {
  display: inline-block;
  width: 32px;
  height: 32px;
  border: 3px solid rgba(220, 31, 67, 0.2);
  border-top-color: var(--primary-color, #dc1f43);
  border-radius: 50%;
  animation: archSpin 0.7s linear infinite;
  margin-bottom: 10px;
}

@keyframes archSpin {
  to { transform: rotate(360deg); }
}

