head.b:template-skin:
/* ==========================================================================
   BLOGGER LAYOUT EDITOR CUSTOMIZATION (صفحة التنسيق)
   تصميم: خالد الرماح ابورقيقة
   ========================================================================== */

body#layout {
  direction: rtl !important;
  font-family: 'Cairo', -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif !important;
  background-color: #f1f5f9 !important;
  color: #1e293b !important;
  padding: 20px !important;
  box-sizing: border-box !important;
}

/* TOP BANNER & COPYRIGHT */
body#layout::before {
  content: "BlogTekMax Pro • تصميم: خالد الرماح ابورقيقة";
  display: block !important;
  background: linear-gradient(135deg, #1e3a8a 0%, #1e40af 50%, #2563eb 100%) !important;
  color: #ffffff !important;
  font-family: 'Cairo', sans-serif;
  font-size: 16px !important;
  font-weight: 800 !important;
  text-align: center !important;
  padding: 14px 24px !important;
  border-radius: 12px !important;
  margin: 0 auto 25px auto !important;
  box-shadow: 0 4px 20px rgba(30, 58, 138, 0.25) !important;
  border: 1px solid rgba(255, 255, 255, 0.2) !important;
  letter-spacing: 0.5px !important;
}

/* LAYOUT SETTINGS SIDEBAR PANEL (RIGHT IN RTL) */
body#layout .layout-settings-panel {
  display: flex !important;
  flex-direction: column !important;
  gap: 16px !important;
  width: 280px !important;
  float: left !important;
  margin-right: 24px !important;
  box-sizing: border-box !important;
}

body#layout .designer-sig-title {
  font-size: 15px !important;
  font-weight: 800 !important;
  color: #1e3a8a !important;
  text-align: center !important;
  padding: 12px !important;
  background: #eff6ff !important;
  border: 2px solid #2563eb !important;
  border-radius: 8px !important;
  margin-bottom: 8px !important;
}

body#layout .designer-sig-sub {
  font-size: 11px !important;
  color: #64748b !important;
  text-align: center !important;
  margin-top: -4px !important;
  margin-bottom: 8px !important;
}

/* SECTION HEADERS (ROYAL BLUE BARS) */
body#layout .section {
  background: #ffffff !important;
  border: 1px solid #e2e8f0 !important;
  border-radius: 10px !important;
  padding: 14px !important;
  margin-bottom: 16px !important;
  box-shadow: 0 1px 4px rgba(0, 0, 0, 0.04) !important;
  box-sizing: border-box !important;
}

body#layout .section h4 {
  background: linear-gradient(135deg, #1e3a8a, #2563eb) !important;
  color: #ffffff !important;
  font-family: 'Cairo', sans-serif;
  font-size: 14px !important;
  font-weight: 700 !important;
  padding: 9px 18px !important;
  border-radius: 7px !important;
  text-align: center !important;
  margin: 0 0 12px 0 !important;
  box-shadow: 0 2px 6px rgba(37, 99, 235, 0.2) !important;
}

/* WIDGET CARDS */
body#layout .widget {
  background: #ffffff !important;
  border: 1px solid #e2e8f0 !important;
  border-radius: 8px !important;
  padding: 10px 14px !important;
  margin-bottom: 8px !important;
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.03) !important;
  font-family: 'Cairo', sans-serif;
}

body#layout .widget:hover {
  border-color: #3b82f6 !important;
  box-shadow: 0 4px 12px rgba(59, 130, 246, 0.1) !important;
}

body#layout .widget h2 {
  font-size: 13px !important;
  font-weight: 700 !important;
  color: #1e293b !important;
  margin: 0 !important;
}

/* ADD A GADGET BUTTON */
body#layout .add-widget,
body#layout a.add-widget-button {
  background: #f8fafc !important;
  border: 1.5px dashed #93c5fd !important;
  border-radius: 8px !important;
  color: #2563eb !important;
  font-size: 13px !important;
  font-weight: 700 !important;
  text-align: center !important;
  padding: 10px 14px !important;
  display: block !important;
  text-decoration: none !important;
  margin-top: 8px !important;
  transition: color 0.2s ease, background-color 0.2s ease, border-color 0.2s ease !important;
}

body#layout .add-widget:hover,
body#layout a.add-widget-button:hover {
  background: #eff6ff !important;
  border-color: #3b82f6 !important;
  color: #1d4ed8 !important;
}

