    (function() {
        try {
            var doc = document.documentElement;
            var cs = getComputedStyle(doc);
            var toggles = [
                ['--show-post-featured-img', 'hide-featured-img'],
                ['--enable-toc', 'hide-toc'],
                ['--enable-reading-progress', 'hide-reading-progress'],
                ['--enable-font-resizer', 'hide-font-resizer'],
                ['--show-reading-time', 'hide-reading-time'],
                ['--enable-related-posts', 'hide-related-posts'],
                ['--enable-author-box', 'hide-author-box'],
                ['--enable-code-copy', 'hide-copy-code'],
                ['--enable-lightbox', 'hide-lightbox'],
                ['--enable-print-btn', 'hide-print-btn'],
                ['--enable-share-btns', 'hide-share-btns'],
                ['--enable-article-series', 'hide-article-series'],
                ['--enable-edit-post', 'hide-edit-post'],
                // 7 Advanced Features & Settings Toggles
                ['--enable-post-info', 'hide-post-info'],
                ['--show-post-author', 'hide-post-author'],
                ['--show-publish-date', 'hide-publish-date'],
                ['--show-updated-date', 'hide-updated-date'],
                ['--show-post-category', 'hide-post-category'],
                ['--show-comment-count', 'hide-comment-count'],
                ['--enable-syntax-highlight', 'no-syntax-highlight'],
                ['--enable-follow-button', 'hide-follow-btn'],
                ['--enable-smart-404', 'hide-smart-404'],
                ['--enable-archive', 'hide-archive'],
                ['--enable-pagination', 'hide-pagination'],
                ['--pagination-show-prevnext', 'hide-pagination-nav'],
                ['--enable-in-article', 'hide-in-article']
            ];
            for (var i = 0; i < toggles.length; i++) {
                var val = (cs.getPropertyValue(toggles[i][0]) || '').trim();
                if (val === '2px' || val === '2') {
                    doc.classList.add(toggles[i][1]);
                }
            }
            var posVal = (cs.getPropertyValue('--follow-btn-pos') || '').trim();
            if (posVal === '3px' || posVal === '3') {
                doc.classList.add('follow-btn-floating');
            } else if (posVal === '2px' || posVal === '2') {
                doc.classList.add('follow-btn-article');
            } else {
                doc.classList.add('follow-btn-header');
            }

            // Synchronous Early Font Loader & Dynamic Stylesheet Dispatcher
            var fontChoice = (cs.getPropertyValue('--font-choice') || '').trim();
            var fontClassMap = { '1px': 'font-cairo', '2px': 'font-tajawal', '3px': 'font-ibm', '4px': 'font-kufi', '5px': 'font-noto' };
            var fontApiMap = {
                '2px': 'Tajawal:wght@400;700',
                '3px': 'IBM+Plex+Sans+Arabic:wght@400;700',
                '4px': 'Noto+Kufi+Arabic:wght@400;700',
                '5px': 'Noto+Sans+Arabic:wght@400;700'
            };
            if (fontClassMap[fontChoice]) {
                doc.classList.add(fontClassMap[fontChoice]);
            }
            if (fontApiMap[fontChoice]) {
                var fLink = document.createElement('link');
                fLink.rel = 'stylesheet';
                fLink.href = 'https://fonts.googleapis.com/css2?family=' + fontApiMap[fontChoice] + '&display=swap';
                document.head.appendChild(fLink);
            }
        } catch (e) {}
    })();
    //

body.script:
//
(function() {
    // 1.8. Highlight Banner Subscription Engine (Connects Layout link to button & prevents anchor jumping)
    (function initHighlightSubscription() {
        function setupBanner() {
            var banner = document.getElementById('highlightBanner') || document.querySelector('.highlight-banner');
            if (!banner) return;
            var btn = banner.querySelector('.highlight-btn');
            var desc = banner.querySelector('.highlight-banner-desc') || banner.querySelector('p');
            if (!btn || !desc) return;

            var targetUrl = '';
            var customBtnText = '';

            // 1. Check if user added an <a> tag via Blogger editor
            var innerLinks = desc.querySelectorAll('a');
            if (innerLinks && innerLinks.length > 0) {
                for (var i = innerLinks.length - 1; i >= 0; i--) {
                    var aTag = innerLinks[i];
                    var href = (aTag.getAttribute('href') || '').trim();
                    if (href && href !== '#' && href !== '#footerSection') {
                        targetUrl = href;
                        var txt = (aTag.textContent || '').trim();
                        if (txt && txt.length < 35 && !txt.startsWith('http')) {
                            customBtnText = txt;
                        }
                        aTag.remove();
                        break;
                    }
                }
            }

            // 2. Check if a raw URL was pasted in the text
            if (!targetUrl) {
                var rawHtml = desc.innerHTML || '';
                var plainText = desc.textContent || '';
                var urlMatch = plainText.match(/(https?:\/\/[^\s<>"'\)]+|mailto:[^\s<>"'\)]+|t\.me\/[^\s<>"'\)]+)/i);
                if (urlMatch) {
                    targetUrl = urlMatch[0];
                    if (targetUrl.indexOf('://') === -1 && targetUrl.indexOf('mailto:') === -1) {
                        targetUrl = 'https://' + targetUrl;
                    }
                    desc.innerHTML = rawHtml.replace(urlMatch[0], '').trim();
                }
            }

            // 3. Connect to button
            if (targetUrl) {
                btn.setAttribute('href', targetUrl);
                btn.setAttribute('target', '_blank');
                btn.setAttribute('rel', 'noopener noreferrer');
                if (customBtnText) {
                    btn.textContent = customBtnText;
                }
                btn.onclick = function(e) {
                    e.stopPropagation();
                };
            } else {
                btn.onclick = function(e) {
                    e.preventDefault();
                    var footer = document.getElementById('footerSection') || document.querySelector('.site-footer');
                    if (footer) {
                        footer.scrollIntoView({ behavior: 'smooth' });
                    }
                };
            }
        }

        if (document.readyState === 'loading') {
            document.addEventListener('DOMContentLoaded', setupBanner);
        } else {
            setupBanner();
        }
    })();

    // Shared in-memory feed cache to eliminate redundant network requests
    var _tmFeedCache = {};
    function tmFetchFeed(url) {
        if (_tmFeedCache[url]) {
            return Promise.resolve(_tmFeedCache[url]);
        }
        return fetch(url).then(function(res) {
            if (!res.ok) throw new Error('HTTP ' + res.status);
            return res.json();
        }).then(function(data) {
            _tmFeedCache[url] = data;
            return data;
        });
    }

    // High-res helper (strictly reserved for Lightbox zoom on user click)
    function getHighRes(url) {
        if (!url) return '';
        return url.replace(/\/s[0-9]+(-c)?\//, '/s1600/').replace(/\/w[0-9]+-h[0-9]+(-c)?\//, '/s1600/');
    }

    // Shared date formatter
    function formatDate(str) {
        try {
            const d = new Date(str);
            return d.toLocaleDateString('ar-EG', { year: 'numeric', month: 'short', day: 'numeric' });
        } catch (e) {
            return str || '';
        }
    }

            // 0. TOP BAR & FOOTER SMART SOCIAL SVG ENGINE (High-Resolution Official SVGs)
