        var items = document.querySelectorAll('.top-social-item, .footer-social-btn, .author-social-links a, .sidebar-social-btn');
        for (var i = 0; i < items.length; i++) {
            var item = items[i];
            var name = (item.getAttribute('data-network') || item.getAttribute('title') || item.getAttribute('aria-label') || item.textContent || '').toLowerCase().trim();
            var href = (item.getAttribute('href') || '').toLowerCase().trim();
            var key = 'generic';

            if (name.indexOf('facebook') !== -1 || name === 'fb' || name.indexOf('فيسبوك') !== -1 || href.indexOf('facebook.com') !== -1 || href.indexOf('fb.com') !== -1) key = 'fb';
            else if (name.indexOf('twitter') !== -1 || name === 'x' || name.indexOf('تويتر') !== -1 || href.indexOf('twitter.com') !== -1 || href.indexOf('x.com') !== -1) key = 'x';
            else if (name.indexOf('instagram') !== -1 || name === 'insta' || name.indexOf('انستغرام') !== -1 || name.indexOf('إنستغرام') !== -1 || href.indexOf('instagram.com') !== -1) key = 'insta';
            else if (name.indexOf('pinterest') !== -1 || name === 'pin' || name.indexOf('بينترست') !== -1 || href.indexOf('pinterest.com') !== -1) key = 'pin';
            else if (name.indexOf('youtube') !== -1 || name === 'yt' || name.indexOf('يوتيوب') !== -1 || href.indexOf('youtube.com') !== -1 || href.indexOf('youtu.be') !== -1) key = 'yt';
            else if (name.indexOf('telegram') !== -1 || name === 'tg' || name.indexOf('تيليجرام') !== -1 || href.indexOf('t.me') !== -1 || href.indexOf('telegram.me') !== -1) key = 'tg';
            else if (name.indexOf('whatsapp') !== -1 || name === 'wa' || name.indexOf('واتساب') !== -1 || href.indexOf('wa.me') !== -1 || href.indexOf('whatsapp.com') !== -1) key = 'wa';
            else if (name.indexOf('linkedin') !== -1 || name.indexOf('لينكد') !== -1 || href.indexOf('linkedin.com') !== -1) key = 'linkedin';
            else if (name.indexOf('tiktok') !== -1 || name.indexOf('تيك توك') !== -1 || href.indexOf('tiktok.com') !== -1) key = 'tiktok';
            else if (name.indexOf('github') !== -1 || name.indexOf('جيت هب') !== -1 || href.indexOf('github.com') !== -1) key = 'github';
            else if (name.indexOf('threads') !== -1 || name.indexOf('ثريدز') !== -1 || href.indexOf('threads.net') !== -1) key = 'threads';
            else if (name.indexOf('vimeo') !== -1 || href.indexOf('vimeo.com') !== -1) key = 'vimeo';
            else if (name.indexOf('rss') !== -1 || href.indexOf('feeds') !== -1 || href.indexOf('rss') !== -1) key = 'rss';

            var label = item.getAttribute('title') || item.getAttribute('aria-label') || name || 'منصة التواصل';
            var iconSpan = item.querySelector('.sidebar-social-icon');
            if (iconSpan) {
                iconSpan.innerHTML = svgMap[key] || svgMap.generic;
            } else {
                item.innerHTML = (svgMap[key] || svgMap.generic) + '<span class="top-social-label sr-only">' + label + '</span>';
            }
        }
    }
    var topSocialDone = false;
    var safeInitTopSocial = function() {
        if (topSocialDone) return;
        initTopSocialIcons();
        topSocialDone = true;
    };
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', safeInitTopSocial);
    } else {
        safeInitTopSocial();
    }

    // 1.5. Editorial Search Modal Controller
    var searchToggle = document.getElementById('searchToggle');
    var searchOverlay = document.getElementById('searchOverlay');
    var searchClose = document.getElementById('searchClose');
    var searchInput = searchOverlay ? searchOverlay.querySelector('input[name="q"]') : null;

    if (searchToggle && searchOverlay) {
        function openSearchModal(e) {
            if (e) e.preventDefault();
            searchOverlay.classList.add('active');
            searchOverlay.setAttribute('aria-hidden', 'false');
            searchToggle.setAttribute('aria-expanded', 'true');
            document.body.style.overflow = 'hidden';
            if (searchInput) {
                setTimeout(function() {
                    searchInput.focus();
                }, 120);
            }
        }
        function closeSearchModal(e) {
            if (e) e.preventDefault();
            searchOverlay.classList.remove('active');
            searchOverlay.setAttribute('aria-hidden', 'true');
            searchToggle.setAttribute('aria-expanded', 'false');
            document.body.style.overflow = '';
            if (searchToggle) {
                try { searchToggle.focus(); } catch (err) {}
            }
        }

        searchToggle.addEventListener('click', openSearchModal);
        if (searchClose) {
            searchClose.addEventListener('click', closeSearchModal);
        }
        searchOverlay.addEventListener('click', function(e) {
            if (e.target === searchOverlay) {
                closeSearchModal();
            }
        });
        document.addEventListener('keydown', function(e) {
            if (e.key === 'Escape' && searchOverlay.classList.contains('active')) {
                closeSearchModal();
            }
        });
    }

    // 1. Dark / Light Theme Controller with Persistence
    var themeToggle = document.getElementById('themeToggle');
    if (themeToggle) {
        var sunSvg = '<svg class="theme-icon-svg icon-sun" fill="none" height="16" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" stroke-width="2" viewBox="0 0 24 24" width="16"><circle cx="12" cy="12" r="4"/><path d="M12 2v2M12 20v2M4.93 4.93l1.41 1.41M17.66 17.66l1.41 1.41M2 12h2M20 12h2M6.34 17.66l-1.41 1.41M19.07 4.93l-1.41 1.41"/></svg>';
        var moonSvg = '<svg class="theme-icon-svg icon-moon" fill="none" height="16" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" stroke-width="2" viewBox="0 0 24 24" width="16"><path d="M12 3a6 6 0 0 0 9 9 9 9 0 1 1-9-9Z"/></svg>';

        function applyThemeUI(theme) {
            if (theme === 'dark') {
                themeToggle.innerHTML = sunSvg;
                themeToggle.setAttribute('aria-label', 'تفعيل المظهر النهاري (الفاتح)');
                themeToggle.setAttribute('title', 'تفعيل المظهر النهاري (الفاتح)');
            } else {
                themeToggle.innerHTML = moonSvg;
                themeToggle.setAttribute('aria-label', 'تفعيل المظهر الليلي (الداكن)');
                themeToggle.setAttribute('title', 'تفعيل المظهر الليلي (الداكن)');
            }
        }

        var activeTheme = document.documentElement.getAttribute('data-theme') || localStorage.getItem('theme') || 'light';
        document.documentElement.setAttribute('data-theme', activeTheme);
        applyThemeUI(activeTheme);

        themeToggle.addEventListener('click', function(e) {
            if (e) e.preventDefault();
            var current = document.documentElement.getAttribute('data-theme');
            var next = (current === 'dark') ? 'light' : 'dark';
            document.documentElement.setAttribute('data-theme', next);
            try {
                localStorage.setItem('theme', next);
            } catch (err) {}
            applyThemeUI(next);
        });
    }

    function initBackToTop() {
        var btn = document.getElementById('backToTopBtn');
        if (!btn) return;

        var rootStyle = getComputedStyle(document.documentElement);
        var enabled = (rootStyle.getPropertyValue('--enable-back-to-top') || '').trim();
        if (enabled === '2px') {
            btn.style.display = 'none';
            return;
        }

        var bttPos = (rootStyle.getPropertyValue('--btt-position') || '').trim();
        if (bttPos === '2px') {
            btn.classList.add('position-right');
        }

        var isVisible = false;
        var threshold = 250;
        var ticking = false;

        function updateBttVisibility() {
            var scrollY = window.pageYOffset || document.documentElement.scrollTop || (document.body ? document.body.scrollTop : 0) || 0;
            var shouldShow = scrollY > threshold;
            if (shouldShow !== isVisible) {
                isVisible = shouldShow;
                if (isVisible) {
                    btn.classList.add('visible');
                } else {
                    btn.classList.remove('visible');
                }
            }
            ticking = false;
        }

        window.addEventListener('scroll', function() {
            if (!ticking) {
                window.requestAnimationFrame(updateBttVisibility);
                ticking = true;
            }
        }, { passive: true });

        // Run initial check
        updateBttVisibility();

        btn.addEventListener('click', function(e) {
            e.preventDefault();
            window.scrollTo({ top: 0, behavior: 'smooth' });
        });
    }

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', initBackToTop);
    } else {
        initBackToTop();
    }

    // 2. Mobile Nav Drawer Toggle
    const mobileToggle = document.getElementById('mobileToggle');
    const navMenu = document.querySelector('.nav-menu-section');
    if (mobileToggle && navMenu) {
        mobileToggle.addEventListener('click', function() {
            const isOpen = navMenu.classList.toggle('open');
            mobileToggle.setAttribute('aria-expanded', isOpen ? 'true' : 'false');
            mobileToggle.setAttribute('aria-label', isOpen ? 'إغلاق القائمة' : 'فتح القائمة');
            navMenu.setAttribute('aria-hidden', isOpen ? 'false' : 'true');
        });
    }

    // 4. SMART RESPONSIVE THUMBNAIL OPTIMIZER FOR NATIVE BLOGGER WIDGETS
    // Protects modern responsive URLs (w400/w200/w800) and ONLY upgrades legacy blurry s72 thumbnails to match container size.
    // NEVER replaces /w.../ with /s1600/ to protect image delivery and save cellular bandwidth!
    function enhanceNativeThumbnails() {
        document.querySelectorAll('.trending-thumb').forEach(function(img) {
            if (img.src && !img.dataset.enhanced) {
                // Only upgrade legacy low-res Blogger thumbnails (/s72/ or /s100/)
                if (/\/s(72|100)(-c)?\//.test(img.src)) {
                    img.src = img.src.replace(/\/s(72|100)(-c)?\//, '/w400-h225-c/');
                }
                img.dataset.enhanced = 'true';
            }
        });
        document.querySelectorAll('.editors-pick-thumb, .compact-post-thumb').forEach(function(img) {
            if (img.src && !img.dataset.enhanced) {
                // Only upgrade legacy low-res Blogger thumbnails (/s72/ or /s100/)
                if (/\/s(72|100)(-c)?\//.test(img.src)) {
                    img.src = img.src.replace(/\/s(72|100)(-c)?\//, '/w200-h125-c/');
                }
                img.dataset.enhanced = 'true';
            }
        });
    }
    enhanceNativeThumbnails();

    // 5. Accessibility: Skip Link Focus Helper (WCAG 2.2 AA)
    var skipLink = document.getElementById('skipToContentLink');
    if (skipLink) {
        skipLink.addEventListener('click', function(e) {
            var target = document.getElementById('main-content');
            if (target) {
                target.setAttribute('tabindex', '-1');
                target.focus();
            }
        });
    }



    // 3. Editors Picks (Sidebar) Hydration & Post Page Fallback Guarantee
    var popList = document.getElementById('popularPostsList');
    if (popList && popList.children.length < 3) {
        var existingLinks = Array.from(popList.querySelectorAll('a')).map(function(a) { return a.href; });
        var streamCards = document.querySelectorAll('.stream-card');

        // If on homepage/archive with stream cards available:
        if (streamCards.length > 0) {
            for (var sIdx = 0; sIdx < streamCards.length && popList.children.length < 3; sIdx++) {
                var sc = streamCards[sIdx];
                var tLink = sc.querySelector('.stream-title a');
                if (!tLink || existingLinks.indexOf(tLink.href) !== -1) continue;
                var imgEl = sc.querySelector('.stream-thumb');
                var art = document.createElement('article');
                art.className = 'editors-pick-card';
                art.innerHTML = '<div class="editors-pick-thumb-wrap"><a href="' + tLink.href + '">' +
                    (imgEl ? '<img src="' + imgEl.src + '" class="editors-pick-thumb" alt="' + tLink.textContent + '" loading="lazy" decoding="async" width="200" height="125"/>' : '') +
                    '</a></div><h4 class="editors-pick-title"><a href="' + tLink.href + '">' + tLink.textContent + '</a></h4>';
                popList.appendChild(art);
                existingLinks.push(tLink.href);
            }
        } else {
            // On single Post pages (where stream cards are not on the page):
            // Defer recent posts feed to guarantee Editor's Picks display without blocking critical render!
            function fetchSidebarFeedDeferred() {
                if (popList.children.length >= 3) return;
                tmFetchFeed('/feeds/posts/default?alt=json&max-results=5')
                    .then(function(data) {
                        var entries = (data.feed && data.feed.entry) ? data.feed.entry : [];
                        var frag = document.createDocumentFragment();
                        entries.forEach(function(e) {
                            if ((popList.children.length + frag.children.length) >= 3) return;
                            var title = e.title ? e.title.$t : '';
                            var linkObj = (e.link || []).find(function(l) { return l.rel === 'alternate'; }) || {};
                            var href = linkObj.href || '#';
                            if (existingLinks.indexOf(href) !== -1) return;
                            if (window.location.href.indexOf(href) !== -1) return;

                            var thumb = '';
                            if (e.media$thumbnail) {
                                thumb = e.media$thumbnail.url.replace(/\/s[0-9]+(-c)?\//, '/w400-h250-c/');
                            } else if (e.content && e.content.$t) {
                                var m = e.content.$t.match(/<img[^>]+src=["']([^"']+)["']/i);
                                if (m) thumb = m[1];
                            }
                            if (!thumb) thumb = 'https://blogger.googleusercontent.com/img/a/AVvXsEh0HuHPYyxoPhs_KGrtvc0bT3JLq4kgq7sHlNC-9D2Y4-zJPk0tVa-VsurXmek_cGE8Sl5wgXMWjyUCBzY6CGRXRjEcT9P8Hu4fBYiiyz4Ajckew616rk68Dd0PbQmQWybN7XnwLsyE6wE2l-tItiMKloIc-uIzxwFuYCK_bt1A2GiIb5anJOZAc-o9OTcL=w400';

                            var art = document.createElement('article');
                            art.className = 'editors-pick-card';
                            art.innerHTML = '<div class="editors-pick-thumb-wrap"><a href="' + href + '">' +
                                '<img src="' + thumb + '" class="editors-pick-thumb" alt="' + title + '" loading="lazy" decoding="async" width="200" height="125"/>' +
                                '</a></div><h4 class="editors-pick-title"><a href="' + href + '">' + title + '</a></h4>';
                            frag.appendChild(art);
                            existingLinks.push(href);
                        });
                        if (frag.children.length > 0) {
                            popList.appendChild(frag);
                        }
                    })
                    .catch(function(err) { console.warn('Sidebar feed:', err); });
            }

            if (window.requestIdleCallback) {
                window.requestIdleCallback(fetchSidebarFeedDeferred, { timeout: 3000 });
            } else {
                window.addEventListener('load', function() {
                    setTimeout(fetchSidebarFeedDeferred, 1200);
                });
            }
        }
    }

})();


// =========================================================================
// BLOGTEKMAX PRO — 7 ADVANCED FEATURES MODULAR ENGINE
// =========================================================================
const TekMaxFeatures = (function() {
    'use strict';

    const isFeatureEnabled = function(cssVar) {
        const rootStyle = getComputedStyle(document.documentElement);
        const val = (rootStyle.getPropertyValue(cssVar) || '').trim();
        return val !== '2px' && val !== '2'; // 1px = enabled (default), 2px = disabled
    };

    const CONFIG = {
        enableCodeCopy: isFeatureEnabled('--enable-code-copy'),
        enableSyntaxHighlight: isFeatureEnabled('--enable-syntax-highlight'),
        enablePostInfo: isFeatureEnabled('--enable-post-info'),
        showPostAuthor: isFeatureEnabled('--show-post-author'),
        showPublishDate: isFeatureEnabled('--show-publish-date'),
        showUpdatedDate: isFeatureEnabled('--show-updated-date'),
        showReadingTime: isFeatureEnabled('--show-reading-time'),
        showPostCategory: isFeatureEnabled('--show-post-category'),
        showCommentCount: isFeatureEnabled('--show-comment-count'),
        enableAdvancedSchema: isFeatureEnabled('--enable-advanced-schema'),
        enableFollowButton: isFeatureEnabled('--enable-follow-button'),
        followButtonPosition: (getComputedStyle(document.documentElement).getPropertyValue('--follow-btn-pos') || '').trim(),
        enableSmart404: isFeatureEnabled('--enable-smart-404'),
        enableArchive: isFeatureEnabled('--enable-archive')
    };

            // 1. MODULE: CodeCopy & 2. MODULE: SyntaxHighlight (GitHub Engine)
    const GitHubCodeEngine = {
        extractCodeText: function(el) {
            var clone = el.cloneNode(true);
            var brs = clone.querySelectorAll('br');
            for (var i = 0; i < brs.length; i++) {
                brs[i].replaceWith('\n');
            }
            var blocks = clone.querySelectorAll('div, p');
            for (var j = 0; j < blocks.length; j++) {
                blocks[j].after('\n');
            }
            var text = clone.textContent || clone.innerText || '';
            text = text.replace(/\u00A0/g, ' ');
            text = text.replace(/^\r?\n+/, '').replace(/\r?\n+$/, '');
            return text;
        },

        isCodeBlock: function(text) {
            var trimmed = text.trim();
            if (!trimmed) return false;

            // Explicit tags: [js], [html], [css], [python], ```, lang: python
            if (/^\s*\[([a-zA-Z0-9#+-]+)\]/i.test(trimmed)) return true;
            if (/^\s*```/i.test(trimmed)) return true;
            if (/^\s*(?:lang|language):\s*\w+/i.test(trimmed)) return true;

            // Code syntax patterns
            var codePatterns = [
                /<\/?(?:html|head|body|div|span|p|a|ul|li|b:[a-z]+|script|style|meta|link)\b/i,
                /<!DOCTYPE\s+html/i,
                /function\s*\(|function\s+[a-zA-Z0-9_$]+\s*\(|=>\s*\{/,
                /\b(?:const|let|var)\s+[a-zA-Z0-9_$]+\s*=/,
                /\b(?:console\.log|document\.getElementById|document\.querySelector)\b/,
                /\b(?:import\s+.*from|export\s+default|export\s+const)\b/,
                /\b(?:def\s+[a-zA-Z0-9_]+\s*\(|import\s+[a-zA-Z0-9_]+|from\s+[a-zA-Z0-9_]+\s+import)\b/,
                /<\?php|\$[a-zA-Z_][a-zA-Z0-9_]*\s*=/,
                /\b(?:SELECT|INSERT\s+INTO|UPDATE\s+\w+\s+SET|DELETE\s+FROM|CREATE\s+TABLE)\b/i,
                /\{[\s\S]*?[a-zA-Z-]+\s*:\s*[^;]+;[\s\S]*?\}/,
                /^\s*(?:npm|yarn|pnpm|git|npx|curl|docker|sudo|pip)\s+[a-z0-9_-]+/im,
                /#include\s*<[a-z0-9_.]+>|#include\s*"[a-z0-9_.]+"/,
                /public\s+class\s+[a-zA-Z0-9_]+|public\s+static\s+void\s+main/
            ];
            for (var i = 0; i < codePatterns.length; i++) {
                if (codePatterns[i].test(trimmed)) return true;
            }

            // Density check for symbols (typical in code, rare in literary prose)
            var symbols = trimmed.match(/[{}\[\]();=><+\-*|&]/g) || [];
            var words = trimmed.split(/\s+/).filter(Boolean);
            if (words.length > 0 && (symbols.length / words.length) > 0.35 && (trimmed.indexOf('{') !== -1 || trimmed.indexOf(';') !== -1 || trimmed.indexOf('=') !== -1)) {
                return true;
            }

            return false;
        },

        detectLanguage: function(code) {
            if (/<!DOCTYPE|<html|<head|<body|<\/?[a-z0-9-]+(\s+[^>]*)?>/i.test(code)) {
                if (/<\/?[a-z]+:[a-z]+/i.test(code)) return 'xml';
                return 'html';
            }
            if (/^(?:SELECT|INSERT|UPDATE|DELETE|CREATE TABLE|ALTER TABLE|DROP TABLE)\b/im.test(code)) return 'sql';
            if (/<\?php|\$[a-zA-Z_\x7f-\xff][a-zA-Z0-9_\x7f-\xff]*\s*=/i.test(code)) return 'php';
            if (/\b(?:def|elif|import\s+[a-zA-Z_]|from\s+[a-zA-Z_].*import|print\s*\()/i.test(code)) return 'python';
            if (/(?:^|\s)(?:#include|#define|int\s+main\s*\(|std::)/i.test(code)) return 'cpp';
            if (/^\s*(\{[\s\S]*\}|\[[\s\S]*\])\s*$/.test(code) && /"[^"]+"\s*:\s*/.test(code)) return 'json';
            if (/([a-zA-Z0-9_-]+|\.[a-zA-Z0-9_-]+|#[a-zA-Z0-9_-]+)\s*\{[^}]*:[^}]*\}/.test(code)) return 'css';
            if (/\b(?:const|let|var|function|console\.log|document\.|window\.|addEventListener|=>|import\s+.*from)\b/.test(code)) return 'javascript';
            if (/^(?:npm|yarn|pnpm|git|npx|curl|docker|sudo|brew|pip)\s+[a-z0-9_-]+/im.test(code)) return 'bash';
            return 'code';
        },

        parseLanguageAndClean: function(rawText) {
            var trimmed = rawText.trim();
            var lang = 'code';
            var cleanCode = rawText;

            var m = trimmed.match(/^\s*\[([a-zA-Z0-9#+-]+)\]\s*[\r\n]?/);
            if (!m) m = trimmed.match(/^\s*(?:lang|language):\s*([a-zA-Z0-9#+-]+)\s*[\r\n]?/i);
            if (!m) m = trimmed.match(/^\s*```([a-zA-Z0-9#+-]*)\s*[\r\n]?/);

            if (m) {
                lang = (m[1] || '').toLowerCase() || 'code';
                cleanCode = rawText.substring(m[0].length).replace(/\s*```\s*$/, '');
            } else {
                lang = this.detectLanguage(trimmed);
            }

            if (lang === 'js') lang = 'javascript';
            if (lang === 'py') lang = 'python';
            if (lang === 'sh') lang = 'bash';
            if (lang === 'yml') lang = 'yaml';

            return { lang: lang, code: cleanCode.trim() };
        },

        getLanguageDisplayName: function(lang) {
            var map = {
                'javascript': 'JavaScript',
                'js': 'JavaScript',
                'html': 'HTML',
                'css': 'CSS',
                'scss': 'SCSS',
                'python': 'Python',
                'py': 'Python',
                'php': 'PHP',
                'sql': 'SQL',
                'json': 'JSON',
                'bash': 'Bash',
                'sh': 'Bash',
                'cpp': 'C++',
                'c': 'C',
                'csharp': 'C#',
                'java': 'Java',
                'xml': 'XML',
                'yaml': 'YAML',
                'code': 'Code'
            };
            return map[lang] || lang.toUpperCase();
        },

        highlightTokens: function(raw, lang) {
            var esc = raw
                .replace(/&/g, '&amp;')
                .replace(/</g, '&lt;')
                .replace(/>/g, '&gt;')
                .replace(/"/g, '&quot;')
                .replace(/'/g, '&#039;');

            var placeholders = [];
            function addToken(match, cssClass) {
                var idx = placeholders.length;
                placeholders.push('<span class="' + cssClass + '">' + match + '</span>');
                return '___TOK_' + idx + '___';
            }

            // 1. Comments
            esc = esc.replace(/\/\*[\s\S]*?\*\/|&lt;!--[\s\S]*?--&gt;/g, function(m) { return addToken(m, 'tok-comm'); });
            if (lang === 'python' || lang === 'bash' || lang === 'php' || lang === 'yaml') {
                esc = esc.replace(/(?:^|\s)(#[^\r\n]*)/g, function(m) { return addToken(m, 'tok-comm'); });
            }
            esc = esc.replace(/\/\/[^\r\n]*/g, function(m) { return addToken(m, 'tok-comm'); });

            // 2. Strings
            esc = esc.replace(/&quot;[\s\S]*?&quot;|&#039;[\s\S]*?&#039;|`[\s\S]*?`/g, function(m) { return addToken(m, 'tok-str'); });

            // 3. Language-specific
            if (lang === 'html' || lang === 'xml') {
                esc = esc.replace(/&lt;\/?b:[a-zA-Z0-9_-]+/g, function(m) { return addToken(m, 'tok-blogger'); });
                esc = esc.replace(/&lt;\/?data:[a-zA-Z0-9._-]+/g, function(m) { return addToken(m, 'tok-blogger'); });
                esc = esc.replace(/&lt;\/?[a-zA-Z0-9_-]+/g, function(m) { return addToken(m, 'tok-tag'); });
                esc = esc.replace(/\b[a-zA-Z0-9_:-]+(?==)/g, function(m) { return addToken(m, 'tok-attr'); });
            } else if (lang === 'css' || lang === 'scss') {
                esc = esc.replace(/\b[a-zA-Z-]+(?=\s*:)/g, function(m) { return addToken(m, 'tok-prop'); });
                esc = esc.replace(/\b\d+(?:\.\d+)?(?:px|rem|em|%|s|ms|deg|vh|vw|fr)?\b/g, function(m) { return addToken(m, 'tok-num'); });
                esc = esc.replace(/#[0-9a-fA-F]{3,8}\b/g, function(m) { return addToken(m, 'tok-num'); });
            } else {
                var kw = [
                    'function','const','let','var','if','else','return','class','import','export','default',
                    'new','this','typeof','async','await','def','elif','print','echo','public','private',
                    'protected','try','catch','throw','finally','for','while','do','switch','case','break',
                    'continue','package','namespace','using','interface','extends','implements','select',
                    'from','where','insert','into','update','delete','create','table','int','string','bool',
                    'boolean','void','true','false','null','undefined','None','True','False','self','lambda',
                    'pass','with','as','yield','in','is','not','and','or'
                ];
                var kwReg = new RegExp('\\b(' + kw.join('|') + ')\\b', 'g');
                esc = esc.replace(kwReg, function(m) { return addToken(m, 'tok-kw'); });
                esc = esc.replace(/\b\d+(?:\.\d+)?\b/g, function(m) { return addToken(m, 'tok-num'); });
                esc = esc.replace(/\b[a-zA-Z0-9_$]+(?=\s*\()/g, function(m) { return addToken(m, 'tok-func'); });
            }

            // Restore
            for (var p = 0; p < placeholders.length; p++) {
                esc = esc.replace('___TOK_' + p + '___', placeholders[p]);
            }

            return esc;
        },

        buildGitHubCodeBox: function(rawCode, lang) {
            var wrapper = document.createElement('div');
            wrapper.className = 'code-block-wrapper gh-code-box gh-converted';
            wrapper.setAttribute('data-lang', lang);

            var langDisplay = this.getLanguageDisplayName(lang);

            var header = document.createElement('div');
            header.className = 'code-block-header gh-code-header';
            header.innerHTML = 
                '<div class="gh-header-left">' +
                    '<span class="gh-mac-dots">' +
                        '<span class="gh-dot gh-dot-red"></span>' +
                        '<span class="gh-dot gh-dot-yellow"></span>' +
                        '<span class="gh-dot gh-dot-green"></span>' +
                    '</span>' +
                    '<span class="code-lang-tag gh-lang-tag">' +
                        '<svg width="13" height="13" viewBox="0 0 16 16" fill="currentColor" style="vertical-align:-2px;margin-left:4px;"><path d="M4.72 3.22a.75.75 0 0 1 1.06 1.06L2.06 8l3.72 3.72a.75.75 0 1 1-1.06 1.06L.47 8.53a.75.75 0 0 1 0-1.06l4.25-4.25zm6.56 0a.75.75 0 0 1 1.06 0l4.25 4.25a.75.75 0 0 1 0 1.06l-4.25 4.25a.75.75 0 0 1-1.06-1.06L13.94 8l-3.72-3.72a.75.75 0 0 1 0-1.06z"/></svg>' +
                        langDisplay +
                    '</span>' +
                '</div>' +
                '<div class="gh-header-right">' +
                    '<button type="button" class="code-copy-btn gh-copy-btn" aria-label="نسخ الكود" title="نسخ الكود">' +
                        '<svg class="gh-copy-icon" width="13" height="13" viewBox="0 0 16 16" fill="currentColor"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"/><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"/></svg>' +
                        '<svg class="gh-check-icon" width="13" height="13" viewBox="0 0 16 16" fill="currentColor" style="display:none;"><path d="M13.78 4.22a.75.75 0 0 1 0 1.06l-7.25 7.25a.75.75 0 0 1-1.06 0L2.22 9.28a.751.751 0 0 1 .018-1.042.751.751 0 0 1 1.042-.018L6 10.94l6.72-6.72a.75.75 0 0 1 1.06 0Z"/></svg>' +
                        '<span class="gh-copy-text">نسخ</span>' +
                    '</button>' +
                '</div>';

            var bodyContainer = document.createElement('div');
            bodyContainer.className = 'gh-code-body';

            var tokenized = (CONFIG.enableSyntaxHighlight) ? this.highlightTokens(rawCode, lang) : rawCode.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

            var lines = rawCode.split('\n');
            var lineNumsHtml = '<div class="gh-line-numbers" aria-hidden="true">';
            for (var i = 1; i <= lines.length; i++) {
                lineNumsHtml += '<span>' + i + '</span>';
            }
            lineNumsHtml += '</div>';

            var pre = document.createElement('pre');
            pre.className = 'gh-pre';
            var code = document.createElement('code');
            code.className = 'gh-code language-' + lang;
            code.innerHTML = tokenized;
            pre.appendChild(code);

            bodyContainer.innerHTML = lineNumsHtml;
            bodyContainer.appendChild(pre);

            wrapper.appendChild(header);
            wrapper.appendChild(bodyContainer);

            var copyBtn = header.querySelector('.code-copy-btn');
            var self = this;
            if (copyBtn) {
                if (!CONFIG.enableCodeCopy) {
                    copyBtn.style.display = 'none';
                }
                copyBtn.addEventListener('click', function() {
                    var copyIcon = copyBtn.querySelector('.gh-copy-icon');
                    var checkIcon = copyBtn.querySelector('.gh-check-icon');
                    var copyTxt = copyBtn.querySelector('.gh-copy-text');

                    function onDone() {
                        copyBtn.classList.add('copied');
                        if (copyIcon) copyIcon.style.display = 'none';
                        if (checkIcon) checkIcon.style.display = 'inline-block';
                        if (copyTxt) copyTxt.textContent = 'تم النسخ ✓';
                        setTimeout(function() {
                            copyBtn.classList.remove('copied');
                            if (copyIcon) copyIcon.style.display = 'inline-block';
                            if (checkIcon) checkIcon.style.display = 'none';
                            if (copyTxt) copyTxt.textContent = 'نسخ';
                        }, 2000);
                    }

                    if (navigator.clipboard && navigator.clipboard.writeText) {
                        navigator.clipboard.writeText(rawCode).then(onDone).catch(function() {
                            self.fallbackCopy(rawCode, onDone);
                        });
                    } else {
                        self.fallbackCopy(rawCode, onDone);
                    }
                });
            }

            return wrapper;
        },

        fallbackCopy: function(text, cb) {
            var ta = document.createElement('textarea');
            ta.value = text;
            ta.style.position = 'fixed';
            ta.style.opacity = '0';
            document.body.appendChild(ta);
            ta.select();
            try { document.execCommand('copy'); if (cb) cb(); } catch(e) {}
            document.body.removeChild(ta);
        },

        processArticleCode: function() {
            var article = document.querySelector('.article-body-content, .article-body, .post-body, .entry-content, .article-wrapper, [itemprop="articleBody"]');
            if (!article || !article.querySelector('pre, blockquote, code')) return;

            var self = this;

            // 1. Process Blockquotes (اقتباس نص من محرر بلوجر)
            var bqs = article.querySelectorAll('blockquote');
            bqs.forEach(function(bq) {
                if (bq.closest('.code-block-wrapper, .gh-code-box') || bq.classList.contains('gh-converted')) return;
                var text = self.extractCodeText(bq);
                if (!text || text.trim().length === 0) return;
                if (!self.isCodeBlock(text)) return; // Keep standard prose quote untouched

                var info = self.parseLanguageAndClean(text);
                var codeBox = self.buildGitHubCodeBox(info.code, info.lang);
                bq.parentNode.replaceChild(codeBox, bq);
            });

            // 2. Process <pre>
            var pres = article.querySelectorAll('pre');
            pres.forEach(function(pre) {
                if (pre.closest('.code-block-wrapper, .gh-code-box') || pre.classList.contains('gh-converted')) return;
                var codeEl = pre.querySelector('code') || pre;
                var text = codeEl.textContent || '';
                if (!text.trim()) return;

                var langMatch = (codeEl.className || '').match(/(?:language-|lang-)([a-zA-Z0-9#+-]+)/);
                var lang = langMatch ? langMatch[1].toLowerCase() : self.detectLanguage(text);

                var codeBox = self.buildGitHubCodeBox(text.trim(), lang);
                pre.parentNode.replaceChild(codeBox, pre);
            });
        },

        init: function() {
            this.processArticleCode();
        }
    };

    // 1. MODULE: CodeCopy
    const CodeCopy = {
        init: function() {
            // Handled gracefully in GitHubCodeEngine
        }
    };

    // 2. MODULE: SyntaxHighlight
    const SyntaxHighlight = {
        init: function() {
            if (!CONFIG.enableSyntaxHighlight && !CONFIG.enableCodeCopy) return;
            GitHubCodeEngine.init();
        }
    };

    // 3. MODULE: PostInfo
    const PostInfo = {
        init: function() {
            const pBox = document.getElementById('postInfoBox') || document.querySelector('.post-info-box');
            if (!CONFIG.enablePostInfo) {
                if (pBox) pBox.style.display = 'none';
                return;
            }

            // Sub-features visibility guards (Scoped to pBox for high performance)
            if (!CONFIG.showPostAuthor) {
                pBox.querySelectorAll('.pinfo-author').forEach(function(el) { el.style.display = 'none'; });
            }
            if (!CONFIG.showPublishDate) {
                pBox.querySelectorAll('.pinfo-published').forEach(function(el) { el.style.display = 'none'; });
            }
            if (!CONFIG.showUpdatedDate) {
                pBox.querySelectorAll('.pinfo-updated').forEach(function(el) { el.style.display = 'none'; });
            }
            if (!CONFIG.showPostCategory) {
                pBox.querySelectorAll('.pinfo-category').forEach(function(el) { el.style.display = 'none'; });
            }
            if (!CONFIG.showCommentCount) {
                pBox.querySelectorAll('.pinfo-comments').forEach(function(el) { el.style.display = 'none'; });
            }
            if (!CONFIG.showReadingTime) {
                pBox.querySelectorAll('.pinfo-reading-time, #pinfoReadingTime').forEach(function(el) { el.style.display = 'none'; });
            } else {
                const article = document.querySelector('.article-body, .post-body, .entry-content, .article-wrapper');
                if (article) {
                    const text = article.innerText || article.textContent || '';
                    const words = text.trim().split(/\s+/).filter(Boolean).length;
                    const readingMinutes = Math.max(1, Math.ceil(words / 190));
                    let rtText = '';
                    if (readingMinutes === 1) {
                        rtText = 'دقيقة واحدة للقراءة';
                    } else if (readingMinutes === 2) {
                        rtText = 'دقيقتان للقراءة';
                    } else if (readingMinutes >= 3 && readingMinutes <= 10) {
                        rtText = readingMinutes + ' دقائق للقراءة';
                    } else {
                        rtText = readingMinutes + ' دقيقة للقراءة';
                    }

                    const pinfoVal = document.querySelector('.pinfo-rt-val');
                    if (pinfoVal) pinfoVal.textContent = rtText;
                }
            }
        }
    };

    // 4. MODULE: SchemaManager (Safe, Non-Destructive Controller for Unified @graph)
    const SchemaManager = {
        init: function() {
            if (!CONFIG.enableAdvancedSchema) {
                // Safe graceful deactivation if user disables advanced schema in Theme Designer
                document.querySelectorAll('script[type="application/ld+json"]').forEach(function(s) {
                    s.remove();
                });
            }
            // With unified @graph architecture, structured data is verified at build-time with Zero Main-Thread overhead.
        }
    };

    // 5. MODULE: FollowButton
    const FollowButton = {
        init: function() {
            const allFollowBtns = document.querySelectorAll('.follow-site-btn, #headerFollowBtn, #floatingFollowBtn, #articleFollowBtn');
            if (!CONFIG.enableFollowButton) {
                allFollowBtns.forEach(function(b) { b.style.display = 'none'; });
                return;
            }

            // Check feed URLs - if empty, fallback to default RSS feed
            allFollowBtns.forEach(function(b) {
                if (!b.getAttribute('href') || b.getAttribute('href') === '#') {
                    b.setAttribute('href', '/feeds/posts/default');
                }
            });

            const pos = (CONFIG.followButtonPosition || '1px').trim();
            const headerBtn = document.getElementById('headerFollowBtn');
            const floatingBtn = document.getElementById('floatingFollowBtn');
            const articleBtn = document.getElementById('articleFollowBtn');

            if (pos === '3px' || pos === '3') {
                // MODE 3: Floating
                if (headerBtn) headerBtn.style.display = 'none';
                if (articleBtn) articleBtn.style.display = 'none';
                if (floatingBtn) floatingBtn.style.display = 'inline-flex';
            } else if (pos === '2px' || pos === '2') {
                // MODE 2: Article
                if (headerBtn) headerBtn.style.display = 'none';
                if (floatingBtn) floatingBtn.style.display = 'none';
                if (articleBtn) articleBtn.style.display = 'inline-flex';
            } else {
                // MODE 1: Header (Default)
                if (floatingBtn) floatingBtn.style.display = 'none';
                if (articleBtn) articleBtn.style.display = 'none';
                if (headerBtn) headerBtn.style.display = 'inline-flex';
            }
        }
    };

    // 6. MODULE: Smart404
    const Smart404 = {
        init: function() {
            const sug = document.getElementById('smart404Suggestions') || document.querySelector('.smart-404-suggestions');
            if (!CONFIG.enableSmart404) {
                if (sug) sug.style.display = 'none';
                return;
            }
            const grid = document.getElementById('smart404Grid');
            if (!grid) return;

            const path = decodeURIComponent(window.location.pathname);
            const cleanSlug = path.replace(/[\/\-_.]/g, ' ').replace(/\b(html|htm|search|label)\b/gi, '').trim();
            const keywords = cleanSlug.split(/\s+/).filter(function(w) { return w.length > 2; });

            let feedUrl = '/feeds/posts/default?alt=json&max-results=4';
            if (keywords.length > 0) {
                feedUrl += '&q=' + encodeURIComponent(keywords.slice(0, 2).join(' '));
            }

            fetch(feedUrl)
                .then(function(res) { return res.json(); })
                .then(function(data) {
                    let entries = (data.feed && data.feed.entry) ? data.feed.entry : [];
                    if (entries.length === 0 && keywords.length > 0) {
                        return fetch('/feeds/posts/default?alt=json&max-results=4')
                            .then(function(r) { return r.json(); })
                            .then(function(d) { return (d.feed && d.feed.entry) ? d.feed.entry : []; });
                    }
                    return entries;
                })
                .then(function(entries) {
                    if (!entries || entries.length === 0) {
                        grid.innerHTML = '<p style="grid-column: 1/-1; text-align: center; color: var(--muted-color);">لا توجد مقالات مقترحة حالياً.</p>';
                        return;
                    }

                    let html = '';
                    entries.forEach(function(entry) {
                        const title = entry.title.$t;
                        let href = '#';
                        if (entry.link) {
                            for (let i = 0; i < entry.link.length; i++) {
                                if (entry.link[i].rel === 'alternate') {
                                    href = entry.link[i].href;
                                    break;
                                }
                            }
                        }
                        let thumb = 'https://blogger.googleusercontent.com/img/a/AVvXsEh0HuHPYyxoPhs_KGrtvc0bT3JLq4kgq7sHlNC-9D2Y4-zJPk0tVa-VsurXmek_cGE8Sl5wgXMWjyUCBzY6CGRXRjEcT9P8Hu4fBYiiyz4Ajckew616rk68Dd0PbQmQWybN7XnwLsyE6wE2l-tItiMKloIc-uIzxwFuYCK_bt1A2GiIb5anJOZAc-o9OTcL=w400';
                        if (entry.media$thumbnail && entry.media$thumbnail.url) {
                            thumb = entry.media$thumbnail.url.replace(/\/s[0-9]+(-c)?\//, '/w480-h270-c/');
                        }
                        const pubDate = entry.published ? new Date(entry.published.$t).toLocaleDateString('ar-EG', { year: 'numeric', month: 'short', day: 'numeric' }) : '';

                        html += '<a href="' + href + '" class="smart-404-card">' +
                            '<img src="' + thumb + '" alt="' + title + '" class="smart-404-card-img" loading="lazy" width="240" height="135"/>' +
                            '<div class="smart-404-card-content">' +
                            '<h4 class="smart-404-card-title">' + title + '</h4>' +
                            '<span class="smart-404-card-meta">' + pubDate + '</span>' +
                            '</div></a>';
                    });
                    grid.innerHTML = html;
                })
                .catch(function() {
                    grid.innerHTML = '<p style="grid-column: 1/-1; text-align: center; color: var(--muted-color);">تعذر تحميل المقالات المقترحة.</p>';
                });
        }
    };

    // 7. MODULE: Archive
    const Archive = {
        init: function() {
            const app = document.getElementById('advancedArchiveApp');
            if (!CONFIG.enableArchive) {
                if (app) app.style.display = 'none';
                return;
            }
            if (!app) return;

            app.innerHTML = '<div class="archive-hero-box">' +
                '<h1 class="archive-hero-title"><svg width="22" height="22" fill="none" stroke="currentColor" stroke-width="2" viewBox="0 0 24 24"><path d="M21 8v13H3V8M1 3h22v5H1zM10 12h4"/></svg><span>أرشيف المقالات</span></h1>' +
                '<p class="archive-hero-desc">تصفح واستكشف جميع المقالات والمواضيع المنشورة في المدونة بكل سهولة وسرعة.</p>' +
            '</div>' +
            '<div class="archive-toolbar">' +
                '<div class="archive-search-box">' +
                '<input type="text" aria-label="ابحث في عناوين الأرشيف" class="archive-search-input" id="archiveSearchInput" placeholder="ابحث في عناوين الأرشيف..." autocomplete="off"/>' +
                '<svg class="archive-search-icon" width="16" height="16" fill="none" stroke="currentColor" stroke-width="2" viewBox="0 0 24 24"><circle cx="11" cy="11" r="8"/><line x1="21" y1="21" x2="16.65" y2="16.65"/></svg>' +
                '</div>' +
                '<select class="archive-year-select" id="archiveYearSelect" aria-label="تصفية المقالات حسب السنة"><option value="all">جميع السنوات</option></select>' +
                '</div></div>' +
                '<div class="archive-state-box" id="archiveState"><span class="archive-spinner"></span><p>جاري فهرسة وتنزيل أرشيف المقالات...</p></div>' +
                '<div class="archive-tree-container" id="archiveTree" style="display: none;"></div>';

            const stateBox = document.getElementById('archiveState');
            const treeContainer = document.getElementById('archiveTree');
            const searchInput = document.getElementById('archiveSearchInput');
            const yearSelect = document.getElementById('archiveYearSelect');

            let allPosts = [];

            fetch('/feeds/posts/summary?alt=json&max-results=150')
                .then(function(res) { return res.json(); })
                .then(function(data) {
                    const entries = (data.feed && data.feed.entry) ? data.feed.entry : [];
                    if (entries.length === 0) {
                        stateBox.innerHTML = '<p class="archive-empty">لا توجد مقالات متوفرة في الأرشيف حالياً.</p>';
                        return;
                    }

                    allPosts = entries.map(function(e) {
                        let link = '#';
                        if (e.link) {
                            for (let i = 0; i < e.link.length; i++) {
                                if (e.link[i].rel === 'alternate') { link = e.link[i].href; break; }
                            }
                        }
                        const d = new Date(e.published ? e.published.$t : Date.now());
                        return {
                            title: e.title.$t,
                            url: link,
                            year: d.getFullYear(),
                            monthIndex: d.getMonth(),
                            monthName: d.toLocaleDateString('ar-EG', { month: 'long' }),
                            dateFormatted: d.toLocaleDateString('ar-EG', { year: 'numeric', month: 'short', day: 'numeric' })
                        };
                    });

                    const yearsSet = {};
                    allPosts.forEach(function(p) { yearsSet[p.year] = true; });
                    const sortedYears = Object.keys(yearsSet).sort(function(a, b) { return b - a; });
                    sortedYears.forEach(function(yr) {
                        const opt = document.createElement('option');
                        opt.value = yr;
                        opt.textContent = 'سنة ' + yr;
                        yearSelect.appendChild(opt);
                    });

                    stateBox.style.display = 'none';
                    treeContainer.style.display = 'flex';
                    Archive.renderTree(allPosts, treeContainer);

                    const onFilterChange = function() {
                        const q = (searchInput.value || '').toLowerCase().trim();
                        const yr = yearSelect.value;
                        const filtered = allPosts.filter(function(p) {
                            const matchQ = !q || p.title.toLowerCase().indexOf(q) !== -1;
                            const matchYr = yr === 'all' || String(p.year) === String(yr);
                            return matchQ && matchYr;
                        });
                        Archive.renderTree(filtered, treeContainer);
                    };

                    searchInput.addEventListener('input', onFilterChange);
                    yearSelect.addEventListener('change', onFilterChange);
                })
                .catch(function() {
                    stateBox.innerHTML = '<p class="archive-error">تعذر تحميل بيانات الأرشيف. <button type="button" onclick="location.reload()" style="margin-right: 8px; padding: 4px 10px; cursor: pointer; border-radius: 4px;">إعادة المحاولة</button></p>';
                });
        },
        renderTree: function(posts, container) {
            if (!posts || posts.length === 0) {
                container.innerHTML = '<div class="archive-state-box"><p>لم يتم العثور على مقالات تطابق بحثك.</p></div>';
                return;
            }

            const tree = {};
            posts.forEach(function(p) {
                if (!tree[p.year]) tree[p.year] = {};
                const mKey = p.monthIndex + '_' + p.monthName;
                if (!tree[p.year][mKey]) tree[p.year][mKey] = [];
                tree[p.year][mKey].push(p);
            });

            let html = '';
            const sortedYears = Object.keys(tree).sort(function(a, b) { return b - a; });

            sortedYears.forEach(function(yr) {
                let totalYearPosts = 0;
                Object.keys(tree[yr]).forEach(function(mk) { totalYearPosts += tree[yr][mk].length; });

                html += '<div class="archive-year-group" data-year="' + yr + '">' +
                    '<div class="archive-year-header" onclick="this.nextElementSibling.style.display = (this.nextElementSibling.style.display === \'none\' ? \'flex\' : \'none\')">' +
                    '<span>📅 سنة ' + yr + '</span>' +
                    '<span class="archive-year-count-badge">' + totalYearPosts + ' مقال</span>' +
                    '</div>' +
                    '<div class="archive-months-wrap">';

                const sortedMonthKeys = Object.keys(tree[yr]).sort(function(a, b) {
                    return parseInt(b.split('_')[0]) - parseInt(a.split('_')[0]);
                });

                sortedMonthKeys.forEach(function(mk) {
                    const mName = mk.split('_')[1];
                    const monthPosts = tree[yr][mk];

                    html += '<div class="archive-month-block">' +
                        '<div class="archive-month-header" onclick="this.nextElementSibling.style.display = (this.nextElementSibling.style.display === \'none\' ? \'flex\' : \'none\')">' +
                        '<span>📂 ' + mName + '</span>' +
                        '<span style="font-size: 0.8rem; color: var(--muted-color); font-weight: 600;">(' + monthPosts.length + ')</span>' +
                        '</div>' +
                        '<ul class="archive-posts-list">';

                    monthPosts.forEach(function(post) {
                        html += '<li class="archive-post-item">' +
                            '<a href="' + post.url + '" class="archive-post-link">' +
                            '<span>' + post.title + '</span>' +
                            '<span class="archive-post-date">' + post.dateFormatted + '</span>' +
                            '</a></li>';
                    });

                    html += '</ul></div>';
                });

                html += '</div></div>';
            });

            container.innerHTML = html;
        }
    };

    // 8. MODULE: SidebarManager (Zero empty space & accessible hidden state via matchMedia)
    const SidebarManager = {
        init: function() {
            const sidebar = document.querySelector('.sidebar');
            if (!sidebar) return;
            const updateSidebarVisibility = function() {
                const isMobile = window.matchMedia && window.matchMedia('(max-width: 991px)').matches;
                if (isMobile) {
                    sidebar.setAttribute('aria-hidden', 'true');
                } else {
                    sidebar.removeAttribute('aria-hidden');
                }
            };
            updateSidebarVisibility();
            if (window.matchMedia) {
                const mql = window.matchMedia('(max-width: 991px)');
                if (mql.addEventListener) {
                    mql.addEventListener('change', updateSidebarVisibility);
                } else if (mql.addListener) {
                    mql.addListener(updateSidebarVisibility);
                }
            } else {
                let resizeTimer = null;
                window.addEventListener('resize', function() {
                    clearTimeout(resizeTimer);
                    resizeTimer = setTimeout(updateSidebarVisibility, 150);
                }, { passive: true });
            }
        }
    };

    return {
        init: function() {
            // Global UI & SEO Managers (Execute safely across all page views)
            SchemaManager.init();
            FollowButton.init();
            SidebarManager.init();

            // View-Specific Guard Clauses: Zero Overhead on Non-Target Pages
            if (document.querySelector('pre, blockquote, code')) {
                CodeCopy.init();
                SyntaxHighlight.init();
            }

            if (document.getElementById('postInfoBox') || document.querySelector('.post-info-box')) {
                PostInfo.init();
            }

            if (document.body.classList.contains('is-error') || document.getElementById('smart404Grid')) {
                Smart404.init();
            }

            if (document.getElementById('advancedArchiveApp')) {
                Archive.init();
            }
        }
    };
})();

if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', TekMaxFeatures.init);
} else {
    TekMaxFeatures.init();
}

