if (explicitType === 'HOMEPAGE') return 'HOMEPAGE';
if (document.body.classList.contains('is-post') || document.body.classList.contains('item-view-post')) return 'POST';
if (document.body.classList.contains('is-page') || document.body.classList.contains('item-view-page')) return 'PAGE';
