}
if (document.querySelector('.tm-error-page')) return 'ERROR';
var postEl = document.querySelector('.single-post, .article-wrapper, .post-body, .article-body-content, [itemprop="articleBody"]');
if (postEl) {
if (document.body && (document.body.classList.contains('item-view-page') || document.body.classList.contains('is-page'))) return 'PAGE';
return 'POST';
}
if (path.indexOf('/search/label/') !== -1) return 'LABEL';
if (path.indexOf('/search') !== -1) return 'SEARCH';
if (path.match(/\/20\d\d\//)) return 'POST';
if (path === '/' || path === '' || (document.body && document.body.classList.contains('is-homepage'))) return 'HOMEPAGE';
return 'INDEX';
}
function getDeviceType() {
