}
function activateAdProvider(container) {
if (!container) return false;
var raw = container.innerHTML || '';
if (!raw.replace(/<!--[\s\S]*?-->/g, '').trim()) {
container.setAttribute('data-ad-state', 'empty');
container.classList.add('tm-ad-empty');
return false;
}
container.setAttribute('data-ad-state', 'loading');
container.classList.add('tm-ad-loading');
var scripts = container.querySelectorAll('script');
for (var s = 0; s < scripts.length; s++) {
var oldScript = scripts[s];
var newScript = document.createElement('script');
for (var a = 0; a < oldScript.attributes.length; a++) {
newScript.setAttribute(oldScript.attributes[a].name, oldScript.attributes[a].value);
}
newScript.text = oldScript.text || oldScript.textContent || '';
if (oldScript.parentNode) {
oldScript.parentNode.replaceChild(newScript, oldScript);
}
}
var insAdSense = container.querySelectorAll('ins.adsbygoogle');
for (var a = 0; a < insAdSense.length; a++) {
var ins = insAdSense[a];
if (ins.getAttribute('data-adsbygoogle-status') !== 'done') {
try {
(window.adsbygoogle = window.adsbygoogle || []).push({});
} catch (e) {
if (TM_ADS_DEBUG) console.warn('[TM ADS] AdSense push notice:', e.message);
}
}
if (typeof MutationObserver !== 'undefined' && !ins._tmObserved) {
ins._tmObserved = true;
(function(targetIns, parentContainer) {
var observer = new MutationObserver(function(mutations) {
for (var m = 0; m < mutations.length; m++) {
if (mutations[m].attributeName === 'data-ad-status') {
var status = targetIns.getAttribute('data-ad-status');
if (status === 'unfilled') {
parentContainer.setAttribute('data-ad-state', 'unfilled');
parentContainer.classList.add('tm-ad-empty');
observer.disconnect();
} else if (status === 'filled') {
parentContainer.setAttribute('data-ad-state', 'filled');
observer.disconnect();
}
}
}
});
observer.observe(targetIns, { attributes: true, attributeFilter: ['data-ad-status'] });
})(ins, container);
}
}
container.setAttribute('data-ad-state', 'filled');
container.classList.remove('tm-ad-loading');
container.classList.add('tm-ad-filled');
return true;
}
function isAdsLazyEnabled() {
try {
var val = getComputedStyle(document.documentElement).getPropertyValue('--enable-ads-lazy').trim();
return val !== '2px';
} catch (e) {
return true;
}
}
var adLazyObserver = null;
if (typeof IntersectionObserver !== 'undefined') {
adLazyObserver = new IntersectionObserver(function(entries, observer) {
entries.forEach(function(entry) {
if (entry.isIntersecting) {
var target = entry.target;
observer.unobserve(target);
activateAdProvider(target);
}
});
}, { rootMargin: '250px 0px' });
}
function queueOrActivateSlot(slot) {
if (!slot) return;
var raw = slot.innerHTML || '';
if (!raw.replace(/<!--[\s\S]*?-->/g, '').trim()) {
slot.setAttribute('data-ad-state', 'empty');
slot.classList.add('tm-ad-empty');
return;
}
if (isAdsLazyEnabled() && adLazyObserver) {
adLazyObserver.observe(slot);
} else {
activateAdProvider(slot);
}
}
function manageStaticSlots() {
var allSlots = document.querySelectorAll('.tm-ad-slot:not(.tm-ad-in-article):not(.tm-ad-in-feed)');
for (var i = 0; i < allSlots.length; i++) {
queueOrActivateSlot(allSlots[i]);
}
}
function findValidBreakpoints(postBody) {
if (!postBody) return [];
var candidates = postBody.querySelectorAll('p, div, blockquote, ul, ol');
var validAnchors = [];
for (var i = 0; i < candidates.length; i++) {
var el = candidates[i];
if (el.closest('.tm-ad-slot, .read-also-inline, .download-box, .tm-toc, pre, code, table, script, style, noscript')) {
continue;
}
var tag = el.tagName.toLowerCase();
if (tag === 'div' && el.querySelector('p, div, ul, ol, table')) {
continue;
}
if (el.classList.contains('separator') || (el.querySelector('img') && (el.textContent || '').trim().length < 25)) {
continue;
}
var txt = (el.textContent || el.innerText || '').trim();
if (txt.length < 15) continue;
validAnchors.push(el);
}
if (validAnchors.length === 0 && postBody.children.length > 0) {
for (var j = 0; j < postBody.children.length; j++) {
var child = postBody.children[j];
if (!child.classList.contains('tm-ad-slot') && !child.classList.contains('separator')) {
validAnchors.push(child);
}
}
}
return validAnchors;
}
function extractTemplateHtml(tplId) {
var tpl = document.getElementById(tplId);
if (!tpl) return '';
var raw = '';
if (tpl.tagName && tpl.tagName.toLowerCase() === 'template') {
raw = tpl.innerHTML || '';
if (!raw.trim() && tpl.content) {
var tmp = document.createElement('div');
tmp.appendChild(tpl.content.cloneNode(true));
raw = tmp.innerHTML || '';
}
} else {
raw = tpl.innerHTML || '';
}
return raw;
}
function runInArticleInjection(postBody) {
if (!postBody) return 0;
var raw1 = extractTemplateHtml('tm-in-article-1-tpl');
var raw2 = extractTemplateHtml('tm-in-article-2-tpl');
var hasAd1 = !!raw1.replace(/<!--[\s\S]*?-->/g, '').trim();
var hasAd2 = !!raw2.replace(/<!--[\s\S]*?-->/g, '').trim();
if (!hasAd1 && !hasAd2) return 0;
var anchors = findValidBreakpoints(postBody);
var total = anchors.length;
var injected = 0;
function injectSlot(htmlCode, anchorEl, extraClass) {
if (!htmlCode) return false;
var wrapper = document.createElement('div');
wrapper.className = 'tm-ad-slot tm-ad-in-article ' + (extraClass || '');
wrapper.setAttribute('data-ad-state', 'loading');
wrapper.innerHTML = htmlCode;
if (anchorEl && anchorEl.parentNode) {
anchorEl.parentNode.insertBefore(wrapper, anchorEl.nextSibling);
} else {
postBody.appendChild(wrapper);
}
activateAdProvider(wrapper);
injected++;
return true;
}
if (total === 0) {
if (hasAd1) injectSlot(raw1, null, 'tm-ad-in-article-1');
if (hasAd2) injectSlot(raw2, null, 'tm-ad-in-article-2');
} else if (total === 1) {
if (hasAd1) injectSlot(raw1, anchors[0], 'tm-ad-in-article-1');
if (hasAd2) injectSlot(raw2, null, 'tm-ad-in-article-2');
} else if (total === 2) {
if (hasAd1) injectSlot(raw1, anchors[0], 'tm-ad-in-article-1');
if (hasAd2) injectSlot(raw2, anchors[1], 'tm-ad-in-article-2');
} else if (total === 3) {
if (hasAd1) injectSlot(raw1, anchors[0], 'tm-ad-in-article-1');
if (hasAd2) injectSlot(raw2, anchors[1], 'tm-ad-in-article-2');
} else {
var idx1 = total >= 6 ? 1 : 0;
if (hasAd1) {
injectSlot(raw1, anchors[idx1], 'tm-ad-in-article-1');
}
if (hasAd2) {
var midIdx = Math.floor(total / 2);
if (midIdx <= idx1) midIdx = idx1 + 1;
if (midIdx >= total) midIdx = total - 1;
injectSlot(raw2, anchors[midIdx], 'tm-ad-in-article-2');
}
}
return injected;
}
function runHomepageInFeed() {
