(function() {
    // --- SMART HERO BENTO COMPLETE HYDRATOR (Guarantees 3 posts: Main + 2 Side Cards) ---
    function ensureHeroComplete() {
        var mainTitle = document.getElementById('heroMainTitle');
        var sideStack = document.getElementById('heroSideStack');
        if (!sideStack) return;

        var subTitle1 = document.getElementById('heroSubTitle1');
        var subTitle2 = document.getElementById('heroSubTitle2');

        var needMain = !mainTitle || mainTitle.textContent.trim() === '';
        var needSide = !subTitle1 || !subTitle2 || !sideStack.children.length || sideStack.children.length < 2;

        if (!needMain && !needSide) return; // Completely filled!

        var mainUrl = mainTitle ? (mainTitle.getAttribute('href') || mainTitle.href || '') : '';

        function populateFromList(posts) {
            if (!posts || posts.length === 0) return;

            // 1. CORE WEB VITALS LCP GUARD: Populate Main Card only if empty
            if (needMain && posts.length > 0) {
                var p0 = posts[0];
                var heroImg = document.getElementById('heroMainImg');
                var heroBadge = document.getElementById('heroMainBadge');
                var heroSnip = document.getElementById('heroMainSnippet');
                var heroDate = document.getElementById('heroMainDate');

                if (mainTitle && p0.title) { mainTitle.textContent = p0.title; mainTitle.href = p0.url; mainUrl = p0.url; }
                if (heroImg && p0.img) { heroImg.src = p0.img; heroImg.alt = p0.title; }
                if (heroBadge && p0.badge) { heroBadge.textContent = p0.badge; }
                if (heroSnip && p0.snippet) { heroSnip.textContent = p0.snippet; heroSnip.style.display = 'block'; }
                if (heroDate && p0.date) {
                    heroDate.innerHTML = '<svg class="meta-icon" fill="none" height="13" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" stroke-width="2" viewBox="0 0 24 24" width="13"><rect height="18" rx="2" ry="2" width="18" x="3" y="4"/><line x1="16" x2="16" y1="2" y2="6"/><line x1="8" x2="8" y1="2" y2="6"/><line x1="3" x2="21" y1="10" y2="10"/></svg><span>' + p0.date + '</span>';
                }
                needMain = false;
            }

            // 2. Populate Side Stack Cards if empty or missing
            if (needSide) {
                // Filter out main post to prevent duplicate
                var available = posts.filter(function(p) {
                    return p.url && (!mainUrl || (p.url !== mainUrl && mainUrl.indexOf(p.url) === -1 && p.url.indexOf(mainUrl) === -1));
                });

                if (available.length >= 1) {
                    sideStack.innerHTML = ''; // Rebuild cleanly
                    for (var idx = 0; idx < Math.min(2, available.length); idx++) {
                        var p = available[idx];
                        var subCard = document.createElement('div');
                        subCard.className = 'hero-sub-card';
                        subCard.innerHTML = '<img class="hero-main-img" decoding="async" height="210" width="400" loading="lazy" src="' + p.img + '" alt="' + p.title + '"/>' +
                            '<div class="hero-gradient-overlay"></div>' +
                            '<div class="hero-sub-content">' +
                                '<span class="badge-tag">' + p.badge + '</span>' +
                                '<h3 class="hero-sub-title"><a href="' + p.url + '">' + p.title + '</a></h3>' +
                                (p.date ? '<span style="font-size:0.78rem; color:rgba(255,255,255,0.75);">' + p.date + '</span>' : '') +
                            '</div>';
                        sideStack.appendChild(subCard);
                    }
                    needSide = false;
                }
            }
        }

        // Try Stream Cards first (Instant, zero network delay)
        var streamCards = document.querySelectorAll('.stream-card');
        if (streamCards.length > 0) {
            var extracted = [];
            for (var s = 0; s < streamCards.length; s++) {
                var sc = streamCards[s];
                var tEl = sc.querySelector('.stream-title a');
                var imgEl = sc.querySelector('.stream-thumb');
                var bEl = sc.querySelector('.badge-tag, .stream-category');
                var sEl = sc.querySelector('.stream-snippet');
                var dEl = sc.querySelector('.stream-meta span:last-child') || sc.querySelector('time');
                if (tEl) {
                    extracted.push({
                        title: tEl.textContent.trim(),
                        url: tEl.href,
                        img: imgEl ? (imgEl.getAttribute('data-src') || imgEl.src) : '',
                        badge: bEl ? bEl.textContent.trim() : 'أخبار',
                        snippet: sEl ? sEl.textContent.trim() : '',
                        date: dEl ? dEl.textContent.trim() : ''
                    });
                }
            }
            if (extracted.length > 0) {
                populateFromList(extracted);
            }
        }

        // If still needs items, fetch feed via shared cached feed utility
        if (needMain || needSide) {
            tmFetchFeed('/feeds/posts/default?alt=json&max-results=5')
                .then(function(data) {
                    var entries = (data.feed && data.feed.entry) ? data.feed.entry : [];
                    var feedList = [];
                    entries.forEach(function(e) {
                        var linkObj = (e.link || []).find(function(l) { return l.rel === 'alternate'; }) || {};
                        var href = linkObj.href || '#';
                        var thumb = '';
                        if (e.media$thumbnail) {
                            thumb = e.media$thumbnail.url.replace(/\/s[0-9]+(-c)?\//, '/w400-h210-c/');
                        } else if (e.content && e.content.$t) {
                            var m = e.content.$t.match(/<img[^>]+src=["']([^"']+)["']/i);
                            if (m) thumb = m[1];
                        }
                        var cat = (e.category && e.category.length > 0) ? e.category[0].term : 'أخبار';
                        var dateStr = e.published ? e.published.$t.substring(0, 10) : '';
                        feedList.push({
                            title: e.title ? e.title.$t : '',
                            url: href,
                            img: thumb || 'https://blogger.googleusercontent.com/img/a/AVvXsEh0HuHPYyxoPhs_KGrtvc0bT3JLq4kgq7sHlNC-9D2Y4-zJPk0tVa-VsurXmek_cGE8Sl5wgXMWjyUCBzY6CGRXRjEcT9P8Hu4fBYiiyz4Ajckew616rk68Dd0PbQmQWybN7XnwLsyE6wE2l-tItiMKloIc-uIzxwFuYCK_bt1A2GiIb5anJOZAc-o9OTcL=w400',
                            badge: cat,
                            snippet: '',
                            date: dateStr
                        });
                    });
                    populateFromList(feedList);
                })
                .catch(function() {});
        }
    }

    ensureHeroComplete();

    function syncHeroFeedDeferred() {
        ensureHeroComplete();
    }

    // STEP C: Trending Grid Completion (Ensures EXACTLY 3 real posts, reuses streamCards)
    var trendGrid = document.getElementById('trendingGrid');
    if (trendGrid && trendGrid.children.length < 3) {
        var existingHrefs = Array.from(trendGrid.querySelectorAll('a')).map(function(a) { return a.href; });
        var allStream = (typeof streamCards !== 'undefined' && streamCards.length > 0) ? streamCards : document.querySelectorAll('.stream-card');
        for (var idx = 0; idx < allStream.length && trendGrid.children.length < 3; idx++) {
            var c = allStream[idx];
            var link = c.querySelector('.stream-title a');
            if (!link || existingHrefs.indexOf(link.href) !== -1) continue;
            var tImg = c.querySelector('.stream-thumb');
            var tDate = c.querySelector('.stream-meta') || c.querySelector('time');
            var art = document.createElement('article');
            art.className = 'trending-card';
            art.innerHTML = '<div class="trending-thumb-wrap"><a href="' + link.href + '">' +
                (tImg ? '<img src="' + tImg.src + '" class="trending-thumb" alt="' + link.textContent + '" loading="lazy" decoding="async" width="400" height="225"/>' : '') +
                '</a></div><h4 class="trending-card-title"><a href="' + link.href + '">' + link.textContent + '</a></h4>' +
                (tDate ? '<span class="trending-card-date">' + tDate.textContent + '</span>' : '');
            trendGrid.appendChild(art);
            existingHrefs.push(link.href);
        }
    }
})();
