(function() {
    'use strict';

    document.addEventListener('DOMContentLoaded', function() {
        var articleBody = document.querySelector('.article-body-content');
        if (!articleBody) return;

        // --- DEDUPLICATE POST FEATURED IMAGE (ZERO FORCED REFLOW) ---
        (function deduplicateFeaturedImage() {
            if (document.documentElement.classList.contains('hide-featured-img')) return;
            var featImg = document.querySelector('.article-featured-img');
            if (!featImg) return;

            var featSrc = (featImg.getAttribute('src') || '').trim();
            function cleanUrl(u) {
                if (!u) return '';
                return u.replace(/\/s[0-9]+(-c)?\//, '/').replace(/\/w[0-9]+-h[0-9]+(-c)?\//, '/').split('?')[0];
            }

            var cleanFeatSrc = cleanUrl(featSrc);
            var fFileName = cleanFeatSrc.split('/').pop();

            // 1. Pure READ Phase (Zero layout thrashing - no interleaving DOM mutations)
            var bodyImgs = articleBody.querySelectorAll('img');
            var toHide = null;
            for (var i = 0; i < Math.min(bodyImgs.length, 3); i++) {
                var bImg = bodyImgs[i];
                var bSrc = cleanUrl(bImg.getAttribute('src') || bImg.getAttribute('data-src') || '');
                var bFileName = bSrc.split('/').pop();

                var isDuplicate = false;
                if (fFileName && bFileName && fFileName === bFileName) {
                    isDuplicate = true;
                } else if (cleanFeatSrc && bSrc && (cleanFeatSrc.indexOf(bSrc) !== -1 || bSrc.indexOf(cleanFeatSrc) !== -1)) {
                    isDuplicate = true;
                } else if (i === 0) {
                    var pParent = bImg.parentElement;
                    if (pParent && (pParent === articleBody.firstElementChild || pParent.parentElement === articleBody.firstElementChild)) {
                        isDuplicate = true;
                    }
                }

                if (isDuplicate) {
                    var container = bImg.closest('.separator') || (bImg.parentElement && bImg.parentElement.tagName.toLowerCase() === 'p' && bImg.parentElement.children.length === 1 ? bImg.parentElement : bImg);
                    toHide = { container: container, img: bImg };
                    break;
                }
            }

            // 2. Pure WRITE Phase (Deferred to requestAnimationFrame to prevent forced reflow)
            requestAnimationFrame(function() {
                document.body.classList.add('has-featured-banner');
                if (toHide) {
                    if (toHide.container) {
                        toHide.container.style.display = 'none';
                        toHide.container.setAttribute('data-duplicate-featured', 'true');
                    }
                    toHide.img.style.display = 'none';
                    toHide.img.setAttribute('data-duplicate-featured', 'true');
                }
            });
        })();


        // --- 2. READING PROGRESS BAR MODULE ---
        (function initReadingProgress() {
            if (document.documentElement.classList.contains('hide-reading-progress')) return;
            var progressBar = document.getElementById('readingProgressBar');
            if (!progressBar) return;

            var ticking = false;
            function updateProgress() {
                var rect = articleBody.getBoundingClientRect();
                var total = rect.height;
                var current = -rect.top;
                var progress = 0;

                if (current > 0) {
                    progress = Math.min(100, Math.max(0, (current / (total - window.innerHeight * 0.5)) * 100));
                }
                progressBar.style.width = progress + '%';
                progressBar.setAttribute('aria-valuenow', Math.round(progress));
                ticking = false;
            }

            window.addEventListener('scroll', function() {
                if (!ticking) {
                    window.requestAnimationFrame(updateProgress);
                    ticking = true;
                }
            }, { passive: true });
        })();

        // --- 3. FONT RESIZER MODULE ---
        (function initFontResizer() {
            if (document.documentElement.classList.contains('hide-font-resizer')) return;
            var decreaseBtn = document.getElementById('fontDecreaseBtn');
            var resetBtn = document.getElementById('fontResetBtn');
            var increaseBtn = document.getElementById('fontIncreaseBtn');
            if (!decreaseBtn || !resetBtn || !increaseBtn) return;

            var defaultSize = 17; // px
            var minSize = 13;
            var maxSize = 24;
            var savedSize = parseInt(localStorage.getItem('tekmax_post_font_size'), 10);
            var currentSize = (!isNaN(savedSize) && savedSize >= minSize && savedSize <= maxSize) ? savedSize : defaultSize;

            function applySize(sz) {
                articleBody.style.fontSize = sz + 'px';
                articleBody.style.lineHeight = (sz >= 20 ? 1.85 : 1.75);
                localStorage.setItem('tekmax_post_font_size', sz);
            }

            if (currentSize !== defaultSize) {
                applySize(currentSize);
            }

            decreaseBtn.addEventListener('click', function() {
                if (currentSize > minSize) {
                    currentSize -= 1;
                    applySize(currentSize);
                }
            });

            resetBtn.addEventListener('click', function() {
                currentSize = defaultSize;
                applySize(currentSize);
            });

            increaseBtn.addEventListener('click', function() {
                if (currentSize < maxSize) {
                    currentSize += 1;
                    applySize(currentSize);
                }
            });
        })();

        // --- 4. PRINT ARTICLE MODULE ---
        (function initPrintArticle() {
            if (document.documentElement.classList.contains('hide-print-btn')) return;
            var printBtn = document.getElementById('printArticleBtn');
            if (!printBtn) return;
            printBtn.addEventListener('click', function() {
                window.print();
            });
        })();

        // --- 5. ADVANCED SHARING & COPY LINK MODULE ---
        (function initSocialSharing() {
            if (document.documentElement.classList.contains('hide-share-btns')) return;
            function getCleanShareUrl(btn) {
                if (btn && btn.getAttribute('data-url')) {
                    return btn.getAttribute('data-url');
                }
                var canonicalLink = document.querySelector('link[rel="canonical"]');
                if (canonicalLink && canonicalLink.href) {
                    return canonicalLink.href;
                }
                return window.location.origin + window.location.pathname;
            }

            // Web Share API & Interactive Dropdown
            var shareBtn = document.getElementById('webShareBtn');
            var shareMenu = document.getElementById('pinfoShareMenu');
            if (shareBtn) {
                shareBtn.addEventListener('click', function(e) {
                    e.stopPropagation();
                    if (navigator.share) {
                        navigator.share({
                            title: document.title,
                            url: getCleanShareUrl(shareBtn)
                        }).catch(function() {});
                    } else if (shareMenu) {
                        var isOpen = shareMenu.style.display === 'flex';
                        shareMenu.style.display = isOpen ? 'none' : 'flex';
                        shareBtn.setAttribute('aria-expanded', !isOpen);
                    }
                });
            }

            if (shareMenu) {
                document.addEventListener('click', function(e) {
                    if (!shareMenu.contains(e.target) && e.target !== shareBtn) {
                        shareMenu.style.display = 'none';
                        if (shareBtn) shareBtn.setAttribute('aria-expanded', 'false');
                    }
                });
            }

            var pinfoCopyBtn = document.getElementById('pinfoCopyBtn');
            if (pinfoCopyBtn) {
                pinfoCopyBtn.addEventListener('click', function(e) {
                    e.stopPropagation();
                    var url = getCleanShareUrl(pinfoCopyBtn);
                    var txt = document.getElementById('pinfoCopyText');
                    function onCopied() {
                        if (txt) {
                            var original = txt.textContent;
                            txt.textContent = 'تم النسخ!';
                            pinfoCopyBtn.style.color = '#10b981';
                            setTimeout(function() {
                                txt.textContent = original;
                                pinfoCopyBtn.style.color = '';
                                if (shareMenu) shareMenu.style.display = 'none';
                            }, 1500);
                        }
                    }
                    if (navigator.clipboard && navigator.clipboard.writeText) {
                        navigator.clipboard.writeText(url).then(onCopied).catch(function() {
                            fallbackCopy(url);
                            onCopied();
                        });
                    } else {
                        fallbackCopy(url);
                        onCopied();
                    }
                });
            }

            // Copy Link
            var copyLinkBtn = document.getElementById('copyArticleLinkBtn');
            if (copyLinkBtn) {
                copyLinkBtn.addEventListener('click', function() {
                    var url = getCleanShareUrl(copyLinkBtn);
                    if (navigator.clipboard && navigator.clipboard.writeText) {
                        navigator.clipboard.writeText(url).then(showCopied).catch(fallbackCopy);
                    } else {
                        fallbackCopy();
                    }

                    function fallbackCopy() {
                        var ta = document.createElement('textarea');
                        ta.value = url;
                        ta.style.position = 'fixed';
                        ta.style.opacity = '0';
                        document.body.appendChild(ta);
                        ta.select();
                        try { document.execCommand('copy'); showCopied(); } catch(e) {}
                        document.body.removeChild(ta);
                    }

                    function showCopied() {
                        var span = copyLinkBtn.querySelector('span');
                        var orig = span ? span.textContent : 'نسخ الرابط';
                        if (span) span.textContent = 'تم النسخ ✓';
                        copyLinkBtn.style.background = '#10b981';
                        copyLinkBtn.style.color = '#ffffff';
                        setTimeout(function() {
                            if (span) span.textContent = orig;
                            copyLinkBtn.style.background = '';
                            copyLinkBtn.style.color = '';
                        }, 2000);
                    }
                });
            }
        })();

        // --- 6. AUTOMATIC TABLE OF CONTENTS (TOC) MODULE (ARROW RIGHT, ICON LEFT, COMPACT) ---
        (function initAutomaticTOC() {
            if (document.documentElement.classList.contains('hide-toc')) return;
            var headings = articleBody.querySelectorAll('h2, h3, h4');
            if (headings.length < 2) return; // Skip if fewer than 2 headings

            var tocContainer = document.createElement('div');
            // COLLAPSED BY DEFAULT
            tocContainer.className = 'tekmax-toc-container collapsed';
            tocContainer.setAttribute('role', 'navigation');
            tocContainer.setAttribute('aria-label', 'جدول المحتويات');

            var tocHeader = document.createElement('div');
            tocHeader.className = 'toc-header';
            // Arrow on Right, Title in middle, List icon on Left
            tocHeader.innerHTML = '<div class="toc-header-right">' +
                '<button type="button" class="toc-toggle-btn" aria-label="عرض أو إخفاء جدول المحتويات" aria-expanded="false">' +
                '<svg class="toc-chevron" viewBox="0 0 24 24"><polyline points="18 15 12 9 6 15"/></svg>' +
                '</button>' +
                '<h3 class="toc-title">جدول المحتويات</h3>' +
                '</div>' +
                '<div class="toc-header-left">' +
                '<span class="toc-icon"><svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><line x1="13" y1="6" x2="3" y2="6"/><line x1="13" y1="12" x2="3" y2="12"/><line x1="13" y1="18" x2="3" y2="18"/><path d="M18 4v4"/><path d="M17 11h2.5a1 1 0 0 1 0 2H17v1h3"/><path d="M17 16.5h2.5a.8.8 0 0 1 0 1.5H18m0 0h1.5a.8.8 0 0 1 0 1.5H17"/></svg></span>' +
                '</div>';

            var tocBody = document.createElement('div');
            tocBody.className = 'toc-body';
            var tocList = document.createElement('ul');
            tocList.className = 'toc-list';

            var h2Count = 0;
            var h3Count = 0;
            var h4Count = 0;

            headings.forEach(function(h, idx) {
                var tag = h.tagName.toLowerCase();
                var numStr = '';

                if (tag === 'h2') {
                    h2Count++;
                    h3Count = 0;
                    h4Count = 0;
                    numStr = h2Count + '.';
                } else if (tag === 'h3') {
                    if (h2Count === 0) h2Count = 1;
                    h3Count++;
                    h4Count = 0;
                    numStr = h2Count + '.' + h3Count + '.';
                } else if (tag === 'h4') {
                    if (h2Count === 0) h2Count = 1;
                    if (h3Count === 0) h3Count = 1;
                    h4Count++;
                    numStr = h2Count + '.' + h3Count + '.' + h4Count + '.';
                }

                var text = (h.textContent || h.innerText || '').trim();
                var id = h.id;
                if (!id) {
                    id = 'tekmax-heading-' + (idx + 1);
                    h.id = id;
                }

                var li = document.createElement('li');
                li.className = 'toc-item toc-level-' + (tag === 'h4' ? '4' : (tag === 'h3' ? '3' : '2'));
                var a = document.createElement('a');
                a.className = 'toc-link';
                a.href = '#' + id;

                a.innerHTML = '<span class="toc-num" dir="ltr">' + numStr + '</span> <span class="toc-text">' + text + '</span>';
                li.appendChild(a);
                tocList.appendChild(li);
            });

            // Delegated click handler on tocList (High Performance & Zero Memory Leaks)
            tocList.addEventListener('click', function(e) {
                var link = e.target.closest('.toc-link');
                if (!link) return;
                e.preventDefault();
                var href = link.getAttribute('href');
                if (!href || href.charAt(0) !== '#') return;
                var targetId = href.substring(1);
                var target = document.getElementById(targetId);
                if (target) {
                    var offset = 90;
                    var top = target.getBoundingClientRect().top + window.pageYOffset - offset;
                    window.scrollTo({ top: top, behavior: 'smooth' });
                    if (history.pushState) history.pushState(null, null, '#' + targetId);
                }
            });

            tocBody.appendChild(tocList);
            tocContainer.appendChild(tocHeader);
            tocContainer.appendChild(tocBody);

            // Toggle logic with ARIA state update
            var toggleBtn = tocHeader.querySelector('.toc-toggle-btn');
            tocHeader.addEventListener('click', function() {
                var isCollapsed = tocContainer.classList.toggle('collapsed');
                if (toggleBtn) {
                    toggleBtn.setAttribute('aria-expanded', isCollapsed ? 'false' : 'true');
                }
            });

            // Insert before first heading
            var firstH = headings[0];
            firstH.parentNode.insertBefore(tocContainer, firstH);
        })();

        // --- 7. COPY CODE MODULE ---
        (function initCopyCode() {
            if (document.documentElement.classList.contains('hide-copy-code')) return;
            function bindCopyBtn(btn, pre) {
                if (!btn || btn.hasAttribute('data-bound')) return;
                btn.setAttribute('data-bound', 'true');
                btn.addEventListener('click', function() {
                    var codeEl = pre.querySelector('code') || pre;
                    var codeClone = codeEl.cloneNode(true);
                    var lineNos = codeClone.querySelectorAll('.line-numbers-rows, .linenumber');
                    lineNos.forEach(function(el) { el.remove(); });
                    var codeText = codeClone.innerText || codeClone.textContent || '';

                    if (navigator.clipboard && navigator.clipboard.writeText) {
                        navigator.clipboard.writeText(codeText).then(onSuccess).catch(fallback);
                    } else {
                        fallback();
                    }

                    function fallback() {
                        var ta = document.createElement('textarea');
                        ta.value = codeText;
                        ta.style.position = 'fixed';
                        ta.style.opacity = '0';
                        document.body.appendChild(ta);
                        ta.select();
                        try { document.execCommand('copy'); onSuccess(); } catch(e) {}
                        document.body.removeChild(ta);
                    }

                    function onSuccess() {
                        btn.classList.add('copied');
                        var span = btn.querySelector('span');
                        if (span) span.textContent = 'تم النسخ ✓';
                        setTimeout(function() {
                            btn.classList.remove('copied');
                            if (span) span.textContent = 'نسخ';
                        }, 2000);
                    }
                });
            }

            var pres = articleBody.querySelectorAll('pre');
            pres.forEach(function(pre) {
                var existingWrapper = pre.closest('.code-block-wrapper, .gh-code-box');
                if (existingWrapper) {
                    var existingBtn = existingWrapper.querySelector('.code-copy-btn');
                    if (existingBtn) bindCopyBtn(existingBtn, pre);
                    return;
                }

                var wrapper = document.createElement('div');
                wrapper.className = 'code-block-wrapper';

                var codeEl = pre.querySelector('code') || pre;
                var langClass = (codeEl.className || '').match(/language-([a-zA-Z0-9]+)/);
                var lang = langClass ? langClass[1] : 'CODE';

                var header = document.createElement('div');
                header.className = 'code-block-header';
                header.innerHTML = '<span class="code-lang-tag">' + lang + '</span><button type="button" class="code-copy-btn" aria-label="نسخ الكود"><svg width="13" height="13" fill="none" stroke="currentColor" stroke-width="2" viewBox="0 0 24 24"><rect x="9" y="9" width="13" height="13" rx="2" ry="2"/><path d="M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1"/></svg><span>نسخ</span></button>';

                pre.parentNode.insertBefore(wrapper, pre);
                wrapper.appendChild(header);
                wrapper.appendChild(pre);

                var copyBtn = header.querySelector('.code-copy-btn');
                bindCopyBtn(copyBtn, pre);
            });
        })();

        // --- 8. IMAGE LIGHTBOX MODULE ---
        (function initLightbox() {
            if (document.documentElement.classList.contains('hide-lightbox')) return;
            if (!articleBody || !articleBody.querySelector('img')) return;
            var lightbox = document.getElementById('tekmaxLightbox');
            if (!lightbox) return;

            var overlay = document.getElementById('lightboxOverlay');
            var closeBtn = document.getElementById('lightboxClose');
            var zoomBtn = document.getElementById('lightboxZoom');
            var prevBtn = document.getElementById('lightboxPrev');
            var nextBtn = document.getElementById('lightboxNext');
            var imgEl = document.getElementById('lightboxImg');
            var counterEl = document.getElementById('lightboxCounter');

            var postImgs = Array.prototype.slice.call(articleBody.querySelectorAll('img')).filter(function(img) {
                // Filter out small avatars, emojis, icons
                return (img.naturalWidth > 150 || img.width > 150 || !img.width);
            });

            if (postImgs.length === 0) return;

            var currentIndex = 0;
            var isZoomed = false;

            function openLightbox(index) {
                currentIndex = index;
                var targetImg = postImgs[currentIndex];
                var src = targetImg.getAttribute('src') || '';
                // Use highest resolution Blogger image if available
                src = src.replace(/\/s[0-9]+(-c)?\//, '/s1600/').replace(/\/w[0-9]+-h[0-9]+(-c)?\//, '/s1600/');
                imgEl.src = src;
                imgEl.alt = targetImg.alt || '';
                counterEl.textContent = (currentIndex + 1) + ' / ' + postImgs.length;
                lightbox.style.display = 'flex';
                lightbox.setAttribute('aria-hidden', 'false');
                document.body.style.overflow = 'hidden';
                isZoomed = false;
                imgEl.classList.remove('zoomed');
                closeBtn.focus();
            }

            function closeLightbox() {
                lightbox.style.display = 'none';
                lightbox.setAttribute('aria-hidden', 'true');
                document.body.style.overflow = '';
                imgEl.src = 'data:image/svg+xml,%3Csvg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1 1"%3E%3C/svg%3E';
                isZoomed = false;
                imgEl.classList.remove('zoomed');
                if (postImgs[currentIndex]) {
                    try { postImgs[currentIndex].focus(); } catch (err) {}
                }
            }

            function showNext() {
                currentIndex = (currentIndex + 1) % postImgs.length;
                openLightbox(currentIndex);
            }

            function showPrev() {
                currentIndex = (currentIndex - 1 + postImgs.length) % postImgs.length;
                openLightbox(currentIndex);
            }

            postImgs.forEach(function(img) {
                img.style.cursor = 'zoom-in';
            });

            // Delegated click handler on postBody for all article images (High Efficiency)
            postBody.addEventListener('click', function(e) {
                var clickedImg = e.target.closest('img');
                if (!clickedImg || !postBody.contains(clickedImg)) return;
                var idx = postImgs.indexOf(clickedImg);
                if (idx !== -1) {
                    e.preventDefault();
                    openLightbox(idx);
                }
            });

            overlay.addEventListener('click', closeLightbox);
            closeBtn.addEventListener('click', closeLightbox);
            prevBtn.addEventListener('click', showPrev);
            nextBtn.addEventListener('click', showNext);

            zoomBtn.addEventListener('click', function() {
                isZoomed = !isZoomed;
                imgEl.classList.toggle('zoomed', isZoomed);
            });

            // Keyboard navigation
            document.addEventListener('keydown', function(e) {
                if (lightbox.style.display !== 'flex') return;
                if (e.key === 'Escape') closeLightbox();
                if (e.key === 'ArrowRight') showPrev(); // RTL: Right is Previous
                if (e.key === 'ArrowLeft') showNext();  // RTL: Left is Next
            });

            // Touch Swipe support
            var touchStartX = 0;
            lightbox.addEventListener('touchstart', function(e) {
                touchStartX = e.changedTouches[0].screenX;
            }, { passive: true });

            lightbox.addEventListener('touchend', function(e) {
                var touchEndX = e.changedTouches[0].screenX;
                var diff = touchStartX - touchEndX;
                if (Math.abs(diff) > 50) {
                    if (diff > 0) showNext(); // Swiped left -> next
                    else showPrev();         // Swiped right -> prev
                }
            }, { passive: true });
        })();

        // --- 9. SMART RELATED & IN-ARTICLE ("شاهد أيضاً") SUITE ---
        (function initRelatedAndInArticle() {
            if (document.documentElement.classList.contains('hide-related-posts')) return;
            var section = document.getElementById('relatedPostsSection');
            var inArticleOn = (getComputedStyle(document.documentElement).getPropertyValue('--enable-in-article') || '').trim() !== '2px';
            if (!section && !inArticleOn) return;

            var grid = document.getElementById('relatedPostsGrid');
            var postBody = document.querySelector('.article-body-content') || document.querySelector('.post-body');

            var labelBadge = document.querySelector('.article-label-badge') || document.querySelector('.label-badge');
            var label = (section && section.getAttribute('data-primary-label')) || (labelBadge ? labelBadge.textContent.trim() : '');
            var currentUrl = (section && section.getAttribute('data-current-url')) || window.location.href;

            var feedUrl = label ? ('/feeds/posts/default/-/' + encodeURIComponent(label) + '?alt=json-in-script&max-results=10') : '/feeds/posts/default?alt=json-in-script&max-results=10';

            // --- 10. IN-ARTICLE RELATED ENGINE ("شاهد أيضاً" داخل فقرات المقال: اختيار من 1 إلى 5 مقالات) ---
            function injectInArticleRelated(entries) {
                if (!entries || entries.length === 0 || !postBody) return;
                var rootStyle = getComputedStyle(document.documentElement);
                var enabled = (rootStyle.getPropertyValue('--enable-in-article') || '').trim();
                if (enabled === '2px') return; // Disabled in Theme Designer

                if (postBody.querySelector('.in-article-related')) return; // Avoid duplicate

                // Find candidate insertion blocks (p, div, or direct content children)
                var candidates = [];
                var allP = postBody.querySelectorAll('p');
                for (var i = 0; i < allP.length; i++) {
                    var el = allP[i];
                    if (el.closest('.tm-ad-slot, .code-block-wrapper, table, .in-article-related, blockquote')) continue;
                    var txt = (el.textContent || '').trim();
                    if (txt.length > 15) candidates.push(el);
                }

                // Fallback for Blogger posts using <div> blocks or without standard <p>
                if (candidates.length === 0) {
                    var children = postBody.children;
                    for (var c = 0; c < children.length; c++) {
                        var child = children[c];
                        if (child.matches && child.matches('.tm-ad-slot, .code-block-wrapper, table, .in-article-related, blockquote, script, style')) continue;
                        var cTxt = (child.textContent || '').trim();
                        if (cTxt.length > 15) candidates.push(child);
                    }
                }

                if (candidates.length === 0) return;

                // Position ratio: 1=50%, 2=25%, 3=40%, 4=60%
                var posSetting = (rootStyle.getPropertyValue('--in-article-pos') || '').trim();
                var ratio = 0.50;
                if (posSetting === '2px') ratio = 0.25;
                else if (posSetting === '3px') ratio = 0.40;
                else if (posSetting === '4px') ratio = 0.60;

                var targetIdx = Math.max(0, Math.min(candidates.length - 1, Math.floor(candidates.length * ratio)));
                var targetEl = candidates[targetIdx];
                if (!targetEl || !targetEl.parentNode) return;

                // Count: user choice from 1 to 5 articles
                var countVal = parseInt((rootStyle.getPropertyValue('--in-article-count') || '2px'), 10) || 2;
                var maxCount = Math.max(1, Math.min(5, countVal));

                var cardsHtml = '';
                var added = 0;
                for (var j = 0; j < entries.length && added < maxCount; j++) {
                    var entry = entries[j];
                    var href = '';
                    if (entry.link) {
                        for (var k = 0; k < entry.link.length; k++) {
                            if (entry.link[k].rel === 'alternate') { href = entry.link[k].href; break; }
                        }
                    }
                    if (!href || href === currentUrl || (currentUrl && href && (currentUrl.indexOf(href) !== -1 || href.indexOf(currentUrl) !== -1))) continue;

                    var title = entry.title ? entry.title.$t : '';
                    var thumb = '';
                    if (entry.media$thumbnail && entry.media$thumbnail.url) {
                        thumb = entry.media$thumbnail.url.replace('/s72-c/', '/w400-h250-c/');
                    } else if (entry.content && entry.content.$t) {
                        var m = entry.content.$t.match(/<img[^>]+src=["']([^"']+)["']/i);
                        if (m) thumb = m[1];
                    }
                    if (!thumb) thumb = 'https://blogger.googleusercontent.com/img/a/AVvXsEh0HuHPYyxoPhs_KGrtvc0bT3JLq4kgq7sHlNC-9D2Y4-zJPk0tVa-VsurXmek_cGE8Sl5wgXMWjyUCBzY6CGRXRjEcT9P8Hu4fBYiiyz4Ajckew616rk68Dd0PbQmQWybN7XnwLsyE6wE2l-tItiMKloIc-uIzxwFuYCK_bt1A2GiIb5anJOZAc-o9OTcL=w400';

                    var pubDate = '';
                    if (entry.published && entry.published.$t) {
                        var d = new Date(entry.published.$t);
                        pubDate = d.toLocaleDateString('ar-EG', { year: 'numeric', month: 'short', day: 'numeric' });
                    }

                    var entryLabel = label;
                    if (entry.category && entry.category.length > 0 && entry.category[0].term) {
                        entryLabel = entry.category[0].term;
                    }

                    var numStr = (added + 1) < 10 ? ('0' + (added + 1)) : (added + 1);

                    cardsHtml += '<a class="in-article-card" href="' + href + '">' +
                        '<div class="in-article-card-main">' +
                            '<span class="in-article-card-num">' + numStr + '</span>' +
                            '<h4 class="in-article-card-title">' + title + '</h4>' +
                        '</div>' +
                        '<span class="in-article-card-arrow">' +
                            '<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round">' +
                                '<line x1="19" y1="12" x2="5" y2="12"></line>' +
                                '<polyline points="12 19 5 12 12 5"></polyline>' +
                            '</svg>' +
                        '</span>' +
                    '</a>';
                    added++;
                }

                if (!cardsHtml) return;

                var container = document.createElement('div');
                container.className = 'in-article-related';
                container.innerHTML = '<div class="in-article-related-header">' +
                    '<span class="in-article-related-icon">' +
                        '<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round">' +
                            '<path d="M2 3h6a4 4 0 0 1 4 4v14a3 3 0 0 0-3-3H2z"/>' +
                            '<path d="M22 3h-6a4 4 0 0 0-4 4v14a3 3 0 0 1 3-3h7z"/>' +
                        '</svg>' +
                    '</span>' +
                    '<span class="in-article-related-title">اقرأ أيضاً:</span>' +
                '</div>' +
                '<div class="in-article-cards-wrap">' + cardsHtml + '</div>';

                targetEl.insertAdjacentElement('afterend', container);
            }

            // Global callback for related feed
            window.tekmaxRelatedCallback = function(data) {
                var entries = (data && data.feed && data.feed.entry) ? data.feed.entry : [];

                // 1. Inject in-article related (from 1 to 5 articles)
                injectInArticleRelated(entries);

                // 2. Populate bottom related posts grid if present
                if (section && grid) {
                    var filtered = entries.filter(function(entry) {
                        var href = '';
                        if (entry.link) {
                            for (var i = 0; i < entry.link.length; i++) {
                                if (entry.link[i].rel === 'alternate') { href = entry.link[i].href; break; }
                            }
                        }
                        return href && !currentUrl.includes(href) && !href.includes(currentUrl);
                    });

                    if (filtered.length === 0) {
                        section.style.display = 'none';
                        return;
                    }

                    grid.innerHTML = '';
                    filtered.slice(0, 3).forEach(function(entry) {
                        var title = entry.title.$t || '';
                        var href = '#';
                        if (entry.link) {
                            for (var i = 0; i < entry.link.length; i++) {
                                if (entry.link[i].rel === 'alternate') { href = entry.link[i].href; break; }
                            }
                        }
                        var thumb = '';
                        if (entry.media$thumbnail && entry.media$thumbnail.url) {
                            thumb = entry.media$thumbnail.url.replace('/s72-c/', '/w640-h360-c/');
                        } else if (entry.content && entry.content.$t) {
                            var m = entry.content.$t.match(/<img[^>]+src=["']([^"']+)["']/i);
                            if (m) thumb = m[1];
                        }
                        if (!thumb) thumb = 'https://blogger.googleusercontent.com/img/a/AVvXsEh0HuHPYyxoPhs_KGrtvc0bT3JLq4kgq7sHlNC-9D2Y4-zJPk0tVa-VsurXmek_cGE8Sl5wgXMWjyUCBzY6CGRXRjEcT9P8Hu4fBYiiyz4Ajckew616rk68Dd0PbQmQWybN7XnwLsyE6wE2l-tItiMKloIc-uIzxwFuYCK_bt1A2GiIb5anJOZAc-o9OTcL=w400';

                        var pubDate = '';
                        if (entry.published && entry.published.$t) {
                            var d = new Date(entry.published.$t);
                            pubDate = d.toLocaleDateString('ar-EG', { year: 'numeric', month: 'short', day: 'numeric' });
                        }

                        var card = document.createElement('div');
                        card.className = 'related-post-card';
                        card.innerHTML = '<div class="related-thumb-wrap"><img src="' + thumb + '" alt="' + title + '" class="related-thumb" loading="lazy" decoding="async" width="300" height="180"/></div><div class="related-content">' + (pubDate ? '<span class="related-date">' + pubDate + '</span>' : '') + '<h4 class="related-title"><a href="' + href + '">' + title + '</a></h4></div>';
                        grid.appendChild(card);
                    });
                }
            };

            var script = document.createElement('script');
            script.src = feedUrl + '&callback=tekmaxRelatedCallback';
            document.body.appendChild(script);
        })();
        // --- 11. ARTICLE SERIES MODULE ---
        (function initArticleSeries() {
            if (document.documentElement.classList.contains('hide-article-series')) return;
            var seriesBox = document.getElementById('articleSeriesBox');
            if (!seriesBox) return;
            var titleEl = document.querySelector('.article-title, h1.entry-title');
            var titleText = titleEl ? (titleEl.innerText || titleEl.textContent || '') : '';
            var seriesMatch = titleText.match(/\[(.*?)\]|\((.*?)\)/);
            if (seriesBox.getAttribute('data-active') === 'true' || seriesMatch) {
                seriesBox.style.display = 'block';
                var sTitle = document.getElementById('seriesTitle');
                if (sTitle && seriesMatch) {
                    sTitle.textContent = seriesMatch[1] || seriesMatch[2];
                }
            }
        })();


    });
})();
