body.script:
//
(function() {
    'use strict';

    function isImageLazyEnabled() {
        try {
            var val = getComputedStyle(document.documentElement).getPropertyValue('--enable-image-lazy').trim();
            return val !== '2px'; // 1px = Enabled (Default), 2px = Disabled
        } catch(e) {
            return true;
        }
    }

    function initImageLazyLoading() {
        var lazyEnabled = isImageLazyEnabled();
        var hasFeaturedImg = !!document.querySelector('.article-featured-img');
        var firstContentImg = !hasFeaturedImg ? document.querySelector('.article-body-content img, .post-body img, .entry-content img') : null;
        var firstStreamImg = (!hasFeaturedImg && !document.getElementById('heroMainImg')) ? document.querySelector('.posts-stream .stream-card:first-child .stream-thumb') : null;

        // Single-pass optimization: 100% Native lazy loading (Zero IntersectionObserver overhead) + Strict LCP Protection
        var imgs = document.querySelectorAll('img');
        imgs.forEach(function(img) {
            // 1. Identify critical above-the-fold & LCP candidate images
            var isLogo = !!img.closest('.site-header, .header-brand, .logo-link') || img.classList.contains('logo-img');
            var isHeroLCP = (img.id === 'heroMainImg') || (!!img.closest('.hero-main-card') && !img.closest('.hero-sub-card, .hero-side-stack'));
            var isFeaturedLCP = img.classList.contains('article-featured-img');
            var isContentLCP = (img === firstContentImg);
            var isStreamLCP = (img === firstStreamImg);

            if (isLogo || isHeroLCP || isFeaturedLCP || isContentLCP || isStreamLCP) {
                // Strict LCP Protection: Never apply lazy loading to critical images
                img.setAttribute('loading', 'eager');
                img.setAttribute('decoding', 'async');
                if (isHeroLCP || isFeaturedLCP || isContentLCP || isStreamLCP) {
                    img.setAttribute('fetchpriority', 'high');
                }
            } else {
                // Off-screen / Below-the-fold images: Native C++ browser engine lazy loading
                if (lazyEnabled) {
                    img.setAttribute('loading', 'lazy');
                    img.setAttribute('decoding', 'async');
                } else {
                    img.setAttribute('loading', 'eager');
                }
            }

            // 2. Preserve CLS: populate dimensions from Blogger data attributes if width/height are missing
            if (!img.getAttribute('width') || !img.getAttribute('height')) {
                var pEl = img.parentElement;
                var ow = img.getAttribute('data-original-width') || (pEl && pEl.getAttribute('data-original-width'));
                var oh = img.getAttribute('data-original-height') || (pEl && pEl.getAttribute('data-original-height'));
                if (ow && oh) {
                    img.setAttribute('width', ow);
                    img.setAttribute('height', oh);
                }
            }

            // External thumbnail sizing handled natively via responsive HTML srcset and sizes
        });
    }

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', initImageLazyLoading, { once: true });
    } else {
        initImageLazyLoading();
    }
})();
